/* FX EdgeFinder Companion — standalone, offline-data-first browser application. */
'use strict';
(() => {
const D=FXD, C=Object.keys(D.CURRENCIES), $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const state={db:null,records:[],assets:new Map(),route:'home',id:null,tab:'overview',currency:'USD',macroTab:'global',filter:'all',query:'',dirty:false,revision:0,saveTimer:null,saveChain:Promise.resolve(),saving:false,record:null,expanded:new Set(),imageUrls:new Map(),settings:{minRR:2,maxRisk:1,defaultRisk:0.5,accountCurrency:'CHF'},toastTimer:null};
const G7_PAIRS=['EURUSD','GBPUSD','AUDUSD','NZDUSD','USDCAD','USDJPY','CADJPY','EURGBP','EURAUD','EURNZD','EURCAD','EURJPY','AUDCAD','NZDCAD','GBPAUD','GBPNZD','GBPCAD','GBPJPY','AUDNZD','AUDJPY','NZDJPY'];
const PAIR_CHECKS=[['edge','EdgeFinder-Kontrast klar','Base vs Quote aus EdgeFinder geprüft; Strong vs Weak ist erkennbar oder bewusst neutral.'],['policy','Zentralbank-/Repricing-Divergenz geprüft','Nicht Leitzins abschreiben, sondern prüfen, welche Seite aktuell hawkisher/dovisher repriced wird.'],['spread','2Y-Differential bestätigt oder widerspricht dokumentiert','Spread jetzt, vor 1 Woche und vor 2 Wochen wird aus Währungen & Rates übernommen.'],['real','EdgeFinder-Realzins-Proxy verglichen','Nur als EdgeFinder-Bestandteil werten, nicht doppelt als unabhängige Bestätigung.'],['driver','Market Driver passt zum Paar','Der Haupttreiber des Marktes unterstützt die Paar-Idee oder der Widerspruch ist notiert.'],['risk','Risk Sentiment / Intermarket passt','Risk-on/off, Öl, China, Carry, Safe Haven usw. je nach Paar beurteilt.'],['event','Catalyst- und News-Risiko akzeptabel','High-impact Events der nächsten Tage sind bekannt und passen zum geplanten Timing.'],['technical','Technischer Blick interessant','Noch keine Entry-Pflicht, aber D1/H4 zeigen ein mögliches Setup oder Watchlist-Grund.']];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const clone=x=>JSON.parse(JSON.stringify(x));
const now=()=>new Date().toISOString();
const localDate=(d=new Date())=>{const x=new Date(d);return [x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-')};
const localDateTime=(d=new Date())=>{const x=new Date(d);return localDate(x)+'T'+String(x.getHours()).padStart(2,'0')+':'+String(x.getMinutes()).padStart(2,'0')};
const dateFmt=d=>{if(!d)return '–';const v=new Date(d);return Number.isNaN(v.getTime())?String(d):new Intl.DateTimeFormat('de-CH',{day:'2-digit',month:'2-digit',year:'numeric'}).format(v)};
const dateTimeFmt=d=>{if(!d)return '–';const v=new Date(d);return Number.isNaN(v.getTime())?String(d):new Intl.DateTimeFormat('de-CH',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(v)};
const fmt=(v,n=2)=>Number.isFinite(Number(v))&&v!==''&&v!==null&&v!==undefined?new Intl.NumberFormat('de-CH',{minimumFractionDigits:n,maximumFractionDigits:n}).format(Number(v)):'–';
const num=x=>x===''||x===null||x===undefined?null:(Number.isFinite(Number(x))?Number(x):null);
const signed=(x,n=2)=>x==null?'–':(x>0?'+':'')+fmt(x,n);
const get=(o,p,def='')=>{let v=o;for(const k of p.split('.')){if(v==null)return def;v=v[k]}return v===undefined||v===null?def:v};
const set=(o,p,value)=>{const parts=p.split('.');let v=o;for(let i=0;i<parts.length-1;i++){if(!v[parts[i]]||typeof v[parts[i]]!=='object')v[parts[i]]={};v=v[parts[i]]}v[parts.at(-1)]=value};
const safeUrl=x=>{try{const u=new URL(String(x));return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const sourceLink=(key,label)=>{const s=D.S[key];return s?`<a class="source-link" href="${attr(s.url)}" target="_blank" rel="noopener noreferrer">${esc(label||s.name)} ↗</a>`:''};
const sourceLinks=keys=>`<div class="source-links">${[...new Set(keys||[])].map(k=>sourceLink(k)).join('')}</div>`;
const badge=(text,tone='neutral')=>`<span class="pill ${tone}">${esc(text)}</span>`;
const panel=(content,cls='')=>`<div class="card ${cls}">${content}</div>`;
const empty=(title,description,action='',label='')=>`<div class="empty-state"><div class="empty-icon">⌁</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action?`<button class="button button-primary" data-action="${action}">${esc(label||'Erstellen')} ↗</button>`:''}</div>`;
const options=(values,selected='',empty=false)=>`${empty?'<option value="">Bitte wählen</option>':''}${values.map(x=>`<option value="${attr(x)}" ${String(selected)===String(x)?'selected':''}>${esc(x)}</option>`).join('')}`;
const statusTone=s=>s==='Offen'?'blue':s==='Bereit'?'good':s==='Geschlossen'?'good':s==='Verworfen'?'bad':s==='Watchlist'?'warn':'neutral';
const field=(id,label,type='text',placeholder='',choices=null,hint='',span='',value='',extra='')=>`<div class="field ${span}"><label for="${attr(id)}">${esc(label)}</label>${type==='textarea'?`<textarea id="${attr(id)}" data-bind="${attr(id)}" placeholder="${attr(placeholder)}" rows="3" ${extra}>${esc(value)}</textarea>`:type==='select'?`<select id="${attr(id)}" data-bind="${attr(id)}" ${extra}>${options(choices||[],value,true)}</select>`:`<input id="${attr(id)}" data-bind="${attr(id)}" type="${attr(type)}" ${type==='number'?'step="any" inputmode="decimal"':''} value="${attr(value)}" placeholder="${attr(placeholder)}" ${extra}>`}${hint?`<span class="hint">${esc(hint)}</span>`:''}</div>`;
const fieldsHtml=(defs,doc,prefix='fields.')=>`<div class="form-grid">${defs.map(f=>field(prefix+f.id,f.label,f.type,f.placeholder,f.options,f.hint,'',get(doc,prefix+f.id))).join('')}</div>`;
const textField=(id,label,value='',placeholder='',span='')=>field(id,label,'text',placeholder,null,'',span,value);
const boxField=(id,label,value='',placeholder='',span='')=>field(id,label,'textarea',placeholder,null,'',span,value);
const sectionHeader=(title,subtitle='',action='')=>`<div class="card-header"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>`;
const pageHead=(eyebrow,title,subtitle,actions='')=>`<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="page-head-actions">${actions}</div></div>`;
const btn=(action,label,kind='outline',extra='')=>`<button type="button" class="button button-${kind}" data-action="${action}" ${extra}>${label}</button>`;
const progress=(done,total)=>`<div class="progress-inline"><div class="progress-track"><div class="progress-fill" style="width:${total?Math.round(done/total*100):0}%"></div></div><div class="progress-caption"><span>${done}/${total} geprüft</span><span>${total?Math.round(done/total*100):0}%</span></div></div>`;
function checklistStats(doc,groups=D.groups){let done=0,total=0,na=0;for(const g of groups)for(const i of g.items){let s=doc.checklist?.[i.id];if(s==='done')done++;else if(s==='na')na++;else total++;}return {done,total:done+total,na,all:done+total+na,missing:total};}
function sourceResourceList(keys){return sourceLinks(keys)}
function toast(message,type='success'){const el=$('#toast');el.textContent=message;el.className='toast show '+type;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),3600)}
function modal(title,body,actions=''){const host=$('#modal');host.innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-label="${attr(title)}"><h2>${esc(title)}</h2>${body}<div class="modal-actions">${actions||btn('close-modal','Schliessen')}</div></div>`;host.querySelector('button,input,select,textarea')?.focus()}
function closeModal(){const host=$('#modal');host.innerHTML='';state.modalHandler=null;state.pendingAction=null}
function confirmAction(title,description,callback,label='Bestätigen',danger=false){state.pendingAction=callback;modal(title,`<p>${esc(description)}</p>`,`${btn('close-modal','Abbrechen')}${btn('confirm-modal',esc(label),danger?'danger':'primary')}`)}
function markDirty(){state.dirty=true;state.revision++;$('#save-status').textContent='Ungespeicherte Änderungen';clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>saveNow(),450)}
function updateRecord(rec){rec.updatedAt=now();markDirty()}
function put(store,value){return new Promise((resolve,reject)=>{const tx=state.db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function del(store,id){return new Promise((resolve,reject)=>{const tx=state.db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function all(store){return new Promise((resolve,reject)=>{const tx=state.db.transaction(store,'readonly');const req=tx.objectStore(store).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function saveNow(){clearTimeout(state.saveTimer);if(!state.dirty)return state.saveChain;const revision=state.revision;const snapshot=state.records.map(clone);const settings=clone(state.settings);state.dirty=false;state.saving=true;$('#save-status').textContent='Speichert …';state.saveChain=state.saveChain.catch(()=>{}).then(async()=>{await put('meta',{key:'settings',value:settings});for(const rec of snapshot)await put('records',rec)}).then(()=>{if(!state.dirty&&state.revision===revision){$('#save-status').textContent='Alles gespeichert';state.saving=false}else{state.saving=false;$('#save-status').textContent='Änderungen ausstehend';if(state.dirty)saveNow()}}).catch(e=>{state.dirty=true;state.saving=false;$('#save-status').textContent='Speichern fehlgeschlagen';toast('Speichern fehlgeschlagen: '+e.message,'error');throw e});return state.saveChain}
async function flush(){if(state.dirty)await saveNow();else await state.saveChain}
function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('Dieser Browser unterstützt keine lokale IndexedDB.'));return}const req=indexedDB.open('fx-trade-desk',1);req.onupgradeneeded=()=>{const db=req.result;for(const store of ['records','assets'])if(!db.objectStoreNames.contains(store))db.createObjectStore(store,{keyPath:'id'});if(!db.objectStoreNames.contains('meta'))db.createObjectStore('meta',{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('Schliesse andere geöffnete Tabs dieser App und lade die Seite neu.'))})}
function defaultRecord(kind){const date=localDate();return kind==='macro'?{id:uid(),kind:'macro',title:'Morgenanalyse '+date,date,createdAt:now(),updatedAt:now(),fields:{},checklist:{},checkNotes:{},currencies:{},pairs:g7PairDefaults(),events:[],images:[],notes:'',conclusion:'',reviewed:false}:{id:uid(),kind:'trade',title:'Neue Trade-Idee',pair:'',direction:'Long',status:'Idee',grade:'Unbewertet',decision:'Offen',createdAt:now(),updatedAt:now(),macroId:'',macroSnapshot:null,fields:{riskPercent:String(state.settings.defaultRisk),horizon:'2–5 Handelstage'},checklist:{},checkNotes:{},factors:{},factorNotes:{},images:[],events:[],journal:[],notes:'',exitPrice:'',closedAt:'',realizedR:'',realizedPnl:'',approvalAt:'',approvalNotes:''}}
function current(){return state.records.find(r=>r.id===state.id)||null}
function findRecord(id){return state.records.find(r=>r.id===id)}
function macroRecords(){return state.records.filter(r=>r.kind==='macro').sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.createdAt).localeCompare(String(a.createdAt)))}
function tradeRecords(){return state.records.filter(r=>r.kind==='trade').sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)))}
function create(kind){const rec=defaultRecord(kind);state.records.unshift(rec);markDirty();navigate(kind==='trade'?'trade':'macro',rec.id)}
function navigate(route,id=null,tab=null){const old=state.route+state.id;state.route=route;state.id=id;state.tab=tab||(route==='trade'?'overview':route==='macro'?'overview':'');state.expanded.clear();if(old!==route+id){state.query='';state.filter='all'}try{if(id&&['trade','macro'].includes(route))history.replaceState(null,'','#/'+route+'/'+id);else if(location.hash)history.replaceState(null,'',location.pathname+location.search)}catch{}render();window.scrollTo({top:0,behavior:'instant'});closeMenu()}
function closeMenu(){$('#sidebar').classList.remove('open');$('#mobile-shade').classList.remove('open')}
function render(){const rec=current();state.record=rec;const route=state.route;const names={home:'Übersicht',macros:'Morgenanalysen',trades:'Trade-Ideen',sources:'EdgeFinder & Quellen',settings:'Backup & Einstellungen',macro:'Morgenanalyse',trade:'Trade-Idee'};$('#breadcrumbs').innerHTML=`Workspace <span>/</span> ${esc(names[route]||'Übersicht')}${rec?' <span>/</span> '+esc(rec.title):''}`;$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.nav===route||(route==='trade'&&x.dataset.nav==='trades')||(route==='macro'&&x.dataset.nav==='macros')));let html='';switch(route){case'home':html=renderHome();break;case'macros':html=renderList('macro');break;case'trades':html=renderList('trade');break;case'macro':html=rec?.kind==='macro'?renderMacro(rec):renderHome();break;case'trade':html=rec?.kind==='trade'?renderTrade(rec):renderHome();break;case'sources':html=renderSources();break;case'settings':html=renderSettings();break;default:html=renderHome()}$('#view').innerHTML=html;refreshLive();}
function renderHome(){const trades=tradeRecords(),macros=macroRecords(),open=trades.filter(t=>t.status==='Offen'),closed=trades.filter(t=>t.status==='Geschlossen'),rs=closed.map(t=>num(t.realizedR)).filter(x=>x!==null),avg=rs.length?rs.reduce((a,b)=>a+b,0)/rs.length:null;return pageHead('Dein Workspace','EdgeFinder zuerst. Zusatzchecks danach.','Dein Trading-Journal als Ergänzung zu EdgeFinder: dokumentieren, was EdgeFinder zeigt – und prüfen, was noch fehlt.',btn('new-macro','+ Morgenanalyse','outline')+btn('new-trade','+ Neue Trade-Idee','primary'))+`<div class="stats-grid">${stat('Aktive Ideen',trades.filter(t=>['Idee','Watchlist','Bereit'].includes(t.status)).length,'Noch nicht ausgeführt')}${stat('Offene Trades',open.length,'Laufende Positionen')}${stat('Morgenanalysen',macros.length,'Gespeicherte Snapshots')}${stat('Ø realisiertes R',avg===null?'–':signed(avg)+'R',rs.length+' dokumentierte Ergebnisse')}</div><div class="welcome card"><div><div class="eyebrow">DEIN MORGENPROZESS</div><h2>Erst verstehen. Dann handeln.</h2><p>EdgeFinder liefert die Basis. Diese App zwingt dich danach zu den Checks, die EdgeFinder nicht sauber ersetzt: aktuelles Zins-Repricing, 2Y-Differentials, dominanter Market Driver, Event-Risiko, technische Invalidierung und Journal-Review.</p><div class="inline-actions mt-16">${btn('new-macro','Morgenanalyse starten','primary')}${btn('new-trade','Trade-Idee erfassen','outline')}</div></div><div class="welcome-symbol">↗</div></div><div class="panel-grid"><div>${panel(`<div class="card-pad">${sectionHeader('Letzte Trade-Ideen','Dein aktueller Analyse- und Trading-Workflow.',btn('go-trades','Alle ansehen','ghost'))}${trades.length?`<div class="list-stack">${trades.slice(0,5).map(t=>recordRow(t)).join('')}</div>`:empty('Noch keine Trade-Ideen','Erstelle deine erste Idee und gehe die Checkliste Schritt für Schritt durch.','new-trade','Erste Idee erstellen')}</div>`)}</div><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Deine letzte Morgenanalyse','Wiederverwenden statt alles neu erfassen.')}${macros.length?`<div class="list-stack">${macros.slice(0,3).map(m=>recordRow(m)).join('')}</div>`:empty('Noch kein Makro-Snapshot','Beginne mit dem heutigen Marktumfeld.','new-macro','Analyse starten')}</div>`)}${panel(`<div class="card-pad">${sectionHeader('Der wichtigste Grundsatz')}<div class="callout-list">${[['01','EdgeFinder ist die Basis','Score, Bias, Real Yield, COT und Sentiment sauber übernehmen.'],['02','Zusatzchecks statt Double Counting','OIS/Futures, 2Y-Differential und Market Driver separat validieren.'],['03','Journal oder es zählt nicht','Jeder Trade braucht These, Invalidierung, Screenshots und Review.']].map(x=>`<div class="callout-item"><div class="callout-number">${x[0]}</div><div><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}</div></div>`)}</div></div>`}
function stat(label,value,foot){return `<div class="card stat-card"><div class="stat-label">${esc(label)}</div><div class="stat-value numeric-value">${esc(value)}</div><div class="stat-foot">${esc(foot)}</div></div>`}
function recordRow(r){const macro=r.kind==='macro',s=checklistStats(r,macro?D.groups.filter(g=>g.macro):D.groups),name=macro?dateFmt(r.date):r.pair||'Paar offen';return `<button class="record-row" data-open="${attr(r.id)}"><div class="record-main"><div class="record-symbol">${macro?'◷':r.direction==='Short'?'↘':'↗'}</div><div style="min-width:0"><div class="record-title">${esc(r.title)}</div><div class="record-sub">${esc(name)} · ${macro?'Morgenanalyse':r.direction+' · '+r.status} · ${dateFmt(r.updatedAt)}</div></div></div><div class="record-meta">${macro?badge(r.reviewed?'Abgeschlossen':'Entwurf',r.reviewed?'good':'neutral'):badge(r.status,statusTone(r.status))}<span class="record-date muted text-small">${dateFmt(r.date||r.createdAt)}</span>${progress(s.done,s.total)}<span class="muted">›</span></div></button>`}
function renderList(kind){const macro=kind==='macro',items=macro?macroRecords():tradeRecords(),filtered=items.filter(r=>(state.filter==='all'||(macro?(state.filter==='reviewed'?r.reviewed:!r.reviewed):r.status===state.filter))&&(!state.query||[r.title,r.pair,r.direction,r.notes].join(' ').toLowerCase().includes(state.query.toLowerCase())));return pageHead('WORKSPACE',macro?'Morgenanalysen':'Trade-Ideen',macro?'Halte den täglichen Makrokontext fest und übernimm einen eingefrorenen Snapshot in deine Trade-Ideen.':'Alle Ideen, offenen Positionen und abgeschlossenen Trades an einem Ort.',btn(macro?'new-macro':'new-trade',macro?'+ Neue Morgenanalyse':'+ Neue Trade-Idee','primary'))+`<div class="toolbar"><div class="field search"><label for="list-search">Suche</label><input id="list-search" data-list-search placeholder="${macro?'Datum, Titel oder Notiz':'Paar, Titel oder Notiz'}" value="${attr(state.query)}"></div><div class="field"><label for="list-filter">Status</label><select id="list-filter" data-list-filter>${options(macro?['all','draft','reviewed']:['all',...D.status],state.filter).replace('>all<','>Alle<').replace('>draft<','>Entwurf<').replace('>reviewed<','>Abgeschlossen<')}</select></div></div><div id="list-results" class="list-stack">${filtered.length?filtered.map(recordRow).join(''):empty(items.length?'Keine Treffer':'Noch keine Einträge',items.length?'Passe deine Suche oder den Statusfilter an.':'Starte mit deiner ersten Analyse.',macro?'new-macro':'new-trade',macro?'Analyse erstellen':'Trade-Idee erstellen')}</div>`}
function renderMacro(m){const tabs=[['overview','Überblick'],['currencies','Währungen & Rates'],['pairs','G7 Paar-Checkliste'],['checklist','Tages-Makro'],['events','Catalysts'],['screenshots','Screenshots']];const body=state.tab==='currencies'?renderCurrencies(m):state.tab==='pairs'?renderPairShortlist(m):state.tab==='checklist'?renderChecklists(m,true):state.tab==='events'?renderEvents(m):state.tab==='screenshots'?renderImages(m):renderMacroOverview(m);return renderDetailHead(m,'MORGENANALYSE','Macro-Snapshot · '+dateFmt(m.date))+renderTabs(tabs)+body}
function renderDetailHead(r,eyebrow,subtitle){return `<div class="detail-banner"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(r.title)}</h1><div class="detail-meta">${esc(subtitle)} · Zuletzt geändert ${dateTimeFmt(r.updatedAt)} ${r.kind==='trade'?badge(r.status,statusTone(r.status)):badge(r.reviewed?'Abgeschlossen':'Entwurf',r.reviewed?'good':'neutral')}</div></div><div class="detail-actions">${btn('duplicate','Duplizieren')}${btn('print','Drucken')}${btn('delete-record','Löschen','ghost')}</div></div>`}
function renderTabs(tabs){return `<div class="tabs" role="tablist" aria-label="Bereiche">${tabs.map(([id,label])=>`<button role="tab" aria-selected="${state.tab===id}" class="tab ${state.tab===id?'active':''}" data-tab="${id}">${esc(label)}</button>`).join('')}</div>`}
function renderMacroOverview(m){const stats=checklistStats(m,D.groups.filter(g=>g.macro));return `<div class="review-strip"><div class="review-cell"><div class="label">Analyse-Datum</div><div class="value">${dateFmt(m.date)}</div></div><div class="review-cell"><div class="label">Checkliste</div><div class="value">${stats.done}/${stats.all} erledigt · ${stats.na} N/A</div></div><div class="review-cell"><div class="label">Status</div><div class="value">${m.reviewed?'Abgeschlossen':'In Bearbeitung'}</div></div></div><div class="panel-grid"><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Überblick erfassen','Der tägliche Snapshot trennt EdgeFinder-Ausgangslage von Zusatzchecks und einzelnen Trade-Ideen.')}<div class="form-grid">${field('date','Analyse-Datum','date','',null,'','',m.date)}${textField('title','Titel',m.title,'Morgenanalyse …','')}${field('fields.asOf','Datenstand / Uhrzeit','datetime-local','',null,'Alle Uhrzeiten in Europe/Zurich interpretieren.','',get(m,'fields.asOf'))}${field('fields.horizon','Analyse-Horizont','select','',['2–5 Handelstage','1–3 Wochen','Beides'],'','',get(m,'fields.horizon'))}</div>${boxField('fields.marketSummary','Was treibt den Markt heute ausserhalb der reinen EdgeFinder-Scorecard?',get(m,'fields.marketSummary'),'1–3 wichtigste Treiber und deren Marktreaktion')}${boxField('fields.overnight','Wichtige Overnight-Entwicklungen',get(m,'fields.overnight'),'Fakten, Veröffentlichungsdatum, Quelle, EdgeFinder-Überschneidung und Interpretation getrennt halten')}${boxField('conclusion','Meine heutige Makro-Zusammenfassung',m.conclusion,'Welche Währungen bevorzuge ich nach EdgeFinder + Zusatzchecks, welche vermeide ich – und warum?')}${boxField('notes','Weitere Notizen',m.notes,'Offene Fragen, Beobachtungen, Watchlist …')}</div>`)}${panel(`<div class="card-pad">${sectionHeader('Dein täglicher Ablauf','Ein Prozess, nicht eine Pflicht zu handeln.')}<div class="callout-list">${[['1','EdgeFinder Baseline','Score, Bias, Real Yield Proxy, COT/Retail und wichtige Score-Komponenten übernehmen.'],['2','Rates-Zusatzcheck','OIS/Futures-Repricing und 2Y-Differentials prüfen.'],['3','Market Driver & Risk','Was dominiert gerade? Bestätigen andere Märkte die Story?'],['4','Pair Selection & Journal','Stärke gegen Schwäche handeln und jede Idee sauber dokumentieren.']].map(x=>`<div class="callout-item"><div class="callout-number">${x[0]}</div><div><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}</div><div class="inline-actions mt-24">${btn('macro-currencies','Währungen analysieren','primary')}${btn('macro-checklist','Checkliste öffnen')}</div></div>`)}</div><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Analyse-Fortschritt')}${progress(stats.done,stats.total)}<p class="text-small mt-16">Die Checkliste kann auch mit begründetem N/A abgeschlossen werden. Fehlende Daten bleiben als Datenlücke sichtbar.</p>${btn('macro-checklist','Makro-Checkliste öffnen','outline')}</div>`)}${panel(`<div class="card-pad">${sectionHeader('Schnellzugriff auf Quellen')}${sourceLinks(['calendar','reuters','fedwatch','treasury','fredreal','cftc'])}<p class="text-small mt-16">Die Links öffnen die Originalquellen. Es werden keine Kurse oder News automatisch geladen.</p></div>`)}${panel(`<div class="card-pad">${sectionHeader('Snapshot abschliessen')}<p class="text-small">Ein abgeschlossener Snapshot bleibt bearbeitbar. Beim Übernehmen in einen Trade wird eine separate Kopie eingefroren.</p>${btn('toggle-review',m.reviewed?'Analyse wieder öffnen':'Als abgeschlossen markieren',m.reviewed?'outline':'primary')}</div>`)}</div></div>`}
function currencyData(m,c){return m.currencies[c]||{}}
function currencyField(c,key,label,type='text',placeholder='',choices=null,hint=''){const v=get(state.record,`currencies.${c}.${key}`);return field(`currencies.${c}.${key}`,label,type,placeholder,choices,hint,'',v)}
function renderCurrencies(m){const c=state.currency,CUR=D.CURRENCIES[c],d=currencyData(m,c),rate=CUR.rate;return `<div class="alert"><strong>Acht Währungen, ein EdgeFinder-kompatibler Prozess.</strong> EdgeFinder ist deine Basis. Fülle hier vor allem Zusatzdaten aus: Zentralbank-Nuancen, Marktpricing, 2Y-Renditen, EdgeFinder-Realzins-Proxy und Quellenstand. Für 2Y arbeitest du fix mit drei Punkten: jetzt, vor 1 Woche und vor 2 Wochen. Ein leerer Wert ist besser als eine erfundene Zahl.</div><div class="currency-tabs">${C.map(x=>`<button class="currency-tab ${x===c?'active':''}" data-currency="${x}">${x}</button>`).join('')}</div><div class="panel-grid"><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader(c+' · '+CUR.name,CUR.bank+' · Einzelwährungsanalyse')}<div class="form-grid">${currencyField(c,'asOf','Datenstand / Uhrzeit','datetime-local')}${currencyField(c,'bankDate','Letzte Zentralbankentscheidung','date')}${currencyField(c,'bankRate','Aktueller Leitzins (%)','number','0.00')}${currencyField(c,'tone','Zentralbank-Ton','select','',['Hawkish','Neutral','Dovish','Unklar'])}${currencyField(c,'pricingNext','Nächste Sitzung: erwartete Veränderung (bp)','number','z. B. -25')}${currencyField(c,'pricing3m','Pricing in 3 Monaten (kumulierte bp)','number','Optional')}${currencyField(c,'pricing12m','Pricing in 12 Monaten (kumulierte bp)','number','Optional')}${currencyField(c,'pricingChange','Änderung der Erwartungen (bp)','number','Seit letzter Woche')}${currencyField(c,'yield2','2Y-Rendite jetzt (%)','number','0.000')}${currencyField(c,'yield2Prev','2Y-Rendite vor 1 Woche (%)','number','0.000')}${currencyField(c,'yield2Prev2','2Y-Rendite vor 2 Wochen (%)','number','0.000')}${currencyField(c,'real','EdgeFinder Real Yield (%)','number','Leitzins − CPI YoY')}${currencyField(c,'realTenor','Realzins-Definition / Methode','text','EdgeFinder: Leitzins − CPI YoY')}${currencyField(c,'bias','Währungs-Bias','select','',D.bias)}${currencyField(c,'confidence','Confidence','select','',['High','Medium','Low'])}</div>${boxField(`currencies.${c}.notes`,'Interpretation',d.notes,'Was hat sich verändert, was ist eingepreist und was könnte den Bias ändern?')}${boxField(`currencies.${c}.source`,'Quellen / Links / Datenstand',d.source,'Originalquelle, Zeitpunkt, ggf. Datenanbieter und Kontrakt')}</div>`)}${panel(`<div class="card-pad">${sectionHeader('Zinsdifferential berechnen','Ein eigenständiger Vergleich für das gewünschte Paar – immer jetzt, vor 1 Woche und vor 2 Wochen.')}<div class="form-grid">${field('fields.compareBase','Base Currency','select','',C,'','',get(m,'fields.compareBase')||'USD')}${field('fields.compareQuote','Quote Currency','select','',C,'','',get(m,'fields.compareQuote')||'JPY')}</div><div id="macro-spread">${spreadHtml(m)}</div></div>`)}</div><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Worauf bei '+c+' achten?')}<p class="text-small">${esc(CUR.focus)}</p><div class="divider"></div><div class="mini-label mb-16">Offizielle & ergänzende Quellen</div>${sourceResourceList([CUR.source,CUR.rate,CUR.yield,...CUR.other])}<div class="divider"></div><p class="text-small no-margin">EdgeFinder deckt bereits viele Rohdaten ab. Hier prüfst du zusätzlich, ob der Markt gerade neu priced und ob die 2Y-Differenz zur Trade-Idee passt.</p></div>`)}${panel(`<div class="card-pad">${sectionHeader('Alle Währungen im Blick','Nur deine dokumentierten Einschätzungen.')}<div class="list-stack">${C.map(x=>{const v=currencyData(m,x);return `<button class="record-row" data-currency="${x}"><div class="record-main"><div class="record-symbol">${x.slice(0,1)}</div><div><div class="record-title">${x}</div><div class="record-sub">${esc(D.CURRENCIES[x].name)}</div></div></div>${v.bias?badge(v.bias,v.bias.includes('Bullish')?'good':v.bias.includes('Bearish')?'bad':'neutral'):badge('Unbewertet')}</button>`}).join('')}</div></div>`)}</div></div>`}
function spreadHtml(m){const a=get(m,'fields.compareBase')||'USD',b=get(m,'fields.compareQuote')||'JPY';if(a===b)return '<p class="text-small">Wähle zwei unterschiedliche Währungen.</p>';const x=currencyData(m,a),y=currencyData(m,b),v=num(x.yield2),w=num(y.yield2),p1=num(x.yield2Prev),q1=num(y.yield2Prev),p2=num(x.yield2Prev2),q2=num(y.yield2Prev2),r1=num(x.real),r2=num(y.real);const spread=v!==null&&w!==null?(v-w)*100:null,prev1=p1!==null&&q1!==null?(p1-q1)*100:null,prev2=p2!==null&&q2!==null?(p2-q2)*100:null,delta1=spread!==null&&prev1!==null?spread-prev1:null,delta2=spread!==null&&prev2!==null?spread-prev2:null,constText=delta1===null?'Für die Veränderung fehlen die 1W-Vergleichswerte.':delta1>0?'Das 2Y-Differential bewegt sich seit letzter Woche zugunsten der Base.':delta1<0?'Das 2Y-Differential bewegt sich seit letzter Woche zugunsten der Quote.':'Das 2Y-Differential ist seit letzter Woche unverändert.';const real=r1!==null&&r2!==null&&x.realTenor&&x.realTenor===y.realTenor?(r1-r2)*100:null;return `<div class="metric-result triple"><div class="review-cell"><div class="label">${a} – ${b} · 2Y Spread jetzt</div><div class="value numeric-value">${spread===null?'Daten fehlen':signed(spread,1)+' bp'}</div></div><div class="review-cell"><div class="label">Veränderung vs. vor 1 Woche</div><div class="value numeric-value">${delta1===null?'Daten fehlen':signed(delta1,1)+' bp'}</div></div><div class="review-cell"><div class="label">Veränderung vs. vor 2 Wochen</div><div class="value numeric-value">${delta2===null?'Daten fehlen':signed(delta2,1)+' bp'}</div></div></div><div class="form-note mt-16 no-margin">${spread===null?'Trage für beide Währungen die 2Y-Renditen ein.':constText}${real!==null?' Vergleichbares EdgeFinder-Real-Yield-Differential: '+signed(real,1)+' bp.':''} ${r1!==null&&r2!==null&&real===null?'Die Real-Yield-Definitionen sind nicht identisch oder fehlen – deshalb kein automatischer Vergleich.':''}</div>`}
function g7PairDefaults(){return G7_PAIRS.map((pair,i)=>({id:'g7-'+pair,pair,order:i+1,direction:'Neutral',status:'Kandidat',confidence:'Medium',edge:'',rates:'',driver:'',technical:'Noch nicht geprüft',checks:{},thesis:'',invalidation:'',notes:''}))}
function pairList(m){if(!Array.isArray(m.pairs))m.pairs=[];const existing=new Map();for(const x of m.pairs){if(!x)continue;const pair=String(x.pair||'').toUpperCase().replace(/[^A-Z]/g,'').slice(0,6);if(pair)existing.set(pair,x)}const list=G7_PAIRS.map((pair,i)=>{const old=existing.get(pair)||{};return {...old,id:old.id||'g7-'+pair,pair,order:i+1,direction:old.direction||'Neutral',status:old.status||'Kandidat',confidence:old.confidence||'Medium',edge:old.edge||'',rates:old.rates||'',driver:old.driver||'',technical:old.technical||'Noch nicht geprüft',checks:old.checks&&typeof old.checks==='object'?old.checks:{},thesis:old.thesis||'',invalidation:old.invalidation||'',notes:old.notes||''}});m.pairs=list;return m.pairs}
function pairData(m,id){return pairList(m).find(x=>x.id===id)||null}
function biasTone(v){return String(v||'').includes('Long')||String(v||'').includes('Bestätigt')?'good':String(v||'').includes('Short')||String(v||'').includes('Widerspricht')?'bad':String(v||'').includes('Nicht')?'warn':'neutral'}
function pairField(id,key,label,type='text',placeholder='',choices=null,hint='',span='',extra=''){const p=pairData(state.record,id)||{};return field(`pairs.${id}.${key}`,label,type,placeholder,choices,hint,span,get(p,key),extra)}
function renderPairShortlist(m){const pairs=pairList(m);const selected=state.pairId&&pairs.some(p=>p.id===state.pairId)?state.pairId:(pairs[0]?.id||'');state.pairId=selected;return `<div class="alert"><strong>G7 Paar-Makro-Checkliste.</strong> Du gibst die Basisdaten einmal unter Währungen & Rates ein. Hier werden alle 21 G7-Paare automatisch daraus abgeleitet: 2Y-Spread jetzt, Veränderung gegen vor 1 Woche und gegen vor 2 Wochen. Du ergänzt nur noch die paarbezogene Interpretation und hakst die Zusatzchecks ab.</div><div class="inline-actions wrap mb-24">${pairs.length?btn('create-trade-from-pair','Gewähltes Paar als Trade-Idee übernehmen','primary'):''}</div><div class="currency-tabs pair-tabs">${pairs.map(p=>`<button class="currency-tab ${p.id===selected?'active':''}" data-pair-tab="${p.id}">${String(p.order||'').padStart(2,'0')} · ${esc(p.pair)}</button>`).join('')}</div>${renderSelectedPair(m,selected)}<div class="mt-24">${panel(`<div class="card-pad">${sectionHeader('Alle 21 G7-Paare im Blick','Diese Übersicht ersetzt die alte Pair-Shortlist. Status setzen, dann nur die besten Paare ins Journal übernehmen.')}<div class="pair-overview">${pairs.map(p=>pairSummaryCard(m,p)).join('')}</div></div>`)}</div>`}
function renderSelectedPair(m,id){const p=pairData(m,id);if(!p)return '';const pair=String(p.pair||'').toUpperCase(),base=pair.slice(0,3),quote=pair.slice(3,6),valid=C.includes(base)&&C.includes(quote)&&base!==quote;return `<div class="panel-grid"><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader((String(p.order||'').padStart(2,'0'))+' · '+pair+' · Paar-Makro-Checkliste','Die Währungsdaten kommen von Währungen & Rates. Hier bewertest du nur den relativen Trade-Kontext.')}<div class="form-note"><strong>Übernommen:</strong> ${esc(base)} vs. ${esc(quote)} · Zentralbanken, 2Y-Werte und Realzins-Proxies werden aus der Tagesanalyse gelesen. Trage hier keine doppelten Rohdaten ein.</div><div class="form-grid">${pairField(id,'direction','Vorläufiger Bias','select','',['Long Bias','Short Bias','Neutral','Nur beobachten'],'Long = Base kaufen / Quote verkaufen.','')}${pairField(id,'status','Status','select','',['Kandidat','Watchlist','Bereit für Trade-Idee','Verworfen'],'','')}${pairField(id,'confidence','Confidence','select','',['High','Medium','Low'],'','')}${pairField(id,'edge','EdgeFinder-Bild','select','',['Base stärker','Quote stärker','Gemischt','Neutral/unklar'],'Was zeigt EdgeFinder relativ?','')}${pairField(id,'rates','Rates-Bild','select','',['Bestätigt Long','Bestätigt Short','Neutral','Widerspricht'],'OIS/Futures + 2Y-Differential.','')}${pairField(id,'driver','Market Driver passt?','select','',['Ja','Teilweise','Nein','Unklar'],'','')}${pairField(id,'technical','Technisches Setup','select','',['Noch nicht geprüft','Setup vorhanden','Warten auf Pullback','Kein Setup'],'','')}</div><div id="pair-spread-${attr(id)}">${pairSpreadHtml(m,p)}</div>${pairChecklistHtml(id,p)}${boxField(`pairs.${id}.thesis`,'Warum ist dieses Paar interessant?',p.thesis,'Strong vs Weak, Rates, Market Driver, Event-Risiko …')}${boxField(`pairs.${id}.invalidation`,'Was würde dieses Paar streichen?',p.invalidation,'Konkrete fundamentale oder technische Invalidierung')}${boxField(`pairs.${id}.notes`,'Notizen / Quellen',p.notes,'Datenstand, Links, offene Fragen …')}<div class="inline-actions mt-16">${btn('create-trade-from-pair','Als Trade-Idee übernehmen','primary')}</div></div>`)}</div><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Automatische 2Y-Auswertung',valid?base+' vs. '+quote:'Noch kein gültiges Paar')}<p class="text-small">Die Werte kommen aus der Währungen-&-Rates-Seite. Trage dort für jede Währung 2Y jetzt, vor 1 Woche und vor 2 Wochen ein. Hier wird daraus automatisch das Differential berechnet.</p>${valid?sourceResourceList([D.CURRENCIES[base].yield,D.CURRENCIES[quote].yield]):''}<div class="divider"></div><p class="text-small no-margin"><strong>Saubere Regel:</strong> Wenn EdgeFinder bullish ist, aber das 2Y-Differential gegen den Trade läuft, ist das kein Detail. Dann muss die These deutlich besser begründet sein.</p></div>`)}${panel(`<div class="card-pad">${sectionHeader('Kandidat bewerten')}<div class="review-list">${[['EdgeFinder relativ klar?',p.edge],['Rates bestätigen?',p.rates],['Market Driver passt?',p.driver],['Technik vorhanden?',p.technical],['Status',p.status]].map(([a,b])=>`<div class="review-item"><strong>${esc(a)}</strong>${badge(b||'Offen',biasTone(b))}</div>`).join('')}</div></div>`)}</div></div>`}
function pairChecklistHtml(id,p){const checks=p.checks||{},done=PAIR_CHECKS.filter(c=>checks[c[0]]==='done').length;return `<div class="section-card mt-16"><div class="section-head"><div class="section-title-group"><div class="section-number">✓</div><div><h3>Paar-Zusatzchecks</h3><p>Abhaken heisst: geprüft. Nicht automatisch bullish.</p></div></div>${badge(done+'/'+PAIR_CHECKS.length,'neutral')}</div><div class="section-content"><div class="checklist">${PAIR_CHECKS.map(c=>{const ok=checks[c[0]]==='done';return `<div class="check-row ${ok?'done':''}"><input class="check-control" type="checkbox" data-pair-check="${attr(id+'.'+c[0])}" ${ok?'checked':''}><div class="check-copy"><div class="check-label">${esc(c[1])}</div><div class="check-note">${esc(c[2])}</div></div><div class="check-tools">${ok?badge('geprüft','good'):badge('offen','neutral')}</div></div>`}).join('')}</div></div></div>`}
function pairSpreadHtml(m,p){const pair=String(p.pair||'').toUpperCase().replace('/',''),base=pair.slice(0,3),quote=pair.slice(3,6),valid=/^[A-Z]{6}$/.test(pair)&&C.includes(base)&&C.includes(quote)&&base!==quote;if(!valid)return '<div class="alert warn mt-16"><strong>Gültiges FX-Paar fehlt.</strong> Beispiel: USDJPY oder EURUSD.</div>';const a=currencyData(m,base),b=currencyData(m,quote),n0=num(a.yield2),m0=num(b.yield2),n1=num(a.yield2Prev),m1=num(b.yield2Prev),n2=num(a.yield2Prev2),m2=num(b.yield2Prev2);const s0=n0!==null&&m0!==null?(n0-m0)*100:null,s1=n1!==null&&m1!==null?(n1-m1)*100:null,s2=n2!==null&&m2!==null?(n2-m2)*100:null,d1=s0!==null&&s1!==null?s0-s1:null,d2=s0!==null&&s2!==null?s0-s2:null;return `<div class="metric-result triple mt-16"><div class="review-cell"><div class="label">${base} – ${quote} · 2Y jetzt</div><div class="value numeric-value">${s0===null?'Daten fehlen':signed(s0,1)+' bp'}</div></div><div class="review-cell"><div class="label">vs. vor 1 Woche</div><div class="value numeric-value">${d1===null?'Daten fehlen':signed(d1,1)+' bp'}</div></div><div class="review-cell"><div class="label">vs. vor 2 Wochen</div><div class="value numeric-value">${d2===null?'Daten fehlen':signed(d2,1)+' bp'}</div></div></div>`}
function pairSummaryCard(m,p){const pair=String(p.pair||'').toUpperCase();return `<button class="pair-card" data-pair-tab="${attr(p.id)}"><div class="pair-card-top"><strong>${esc(pair||'Paar offen')}</strong>${badge(p.status||'Kandidat',biasTone(p.status))}</div><div class="pair-card-meta">${esc(p.direction||'Bias offen')} · ${esc(p.confidence||'Confidence offen')}</div>${pairSpreadHtml(m,p)}</button>`}
function renderChecklists(doc,macro=false){const groups=D.groups.filter(g=>!macro||g.macro);const stats=checklistStats(doc,groups);const intro=macro?'Die Makro-Säulen für deinen täglichen Snapshot.':'Die vollständige Validierung für diesen Trade. EdgeFinder ist die Basis; hier dokumentierst du das Ergebnis, vermeidest Double Counting und prüfst die Lücken.';return `<div class="flex-between wrap mb-24"><div><h2 class="no-margin">${macro?'Makro-Checkliste':'Trade-Validation-Checkliste'}</h2><p class="text-small no-margin">${esc(intro)}</p></div><div class="inline-actions">${btn('expand-all','Alle Hilfen öffnen','ghost')}${btn('collapse-all','Hilfen schliessen','ghost')}</div></div><div class="review-strip"><div class="review-cell"><div class="label">Erledigt</div><div class="value">${stats.done} / ${stats.all}</div></div><div class="review-cell"><div class="label">Nicht anwendbar</div><div class="value">${stats.na} begründet</div></div><div class="review-cell"><div class="label">Noch offen</div><div class="value">${stats.missing}</div></div></div><div class="alert"><strong>So funktioniert die Checkliste:</strong> Haken bedeutet tatsächlich geprüft. N/A ist für nicht verfügbare oder nicht anwendbare Punkte und verlangt eine Begründung. Mit „?“ öffnest du eine kurze Anleitung und die passenden Quellen. EdgeFinder-Realzins, Inflation/Rates und 2Y dürfen nicht als drei komplett unabhängige Stimmen gezählt werden.</div>${groups.map(g=>renderCheckGroup(doc,g)).join('')}`}
function renderCheckGroup(doc,g){const stats=checklistStats(doc,[g]);return `<section class="card section-card" id="section-${g.id}"><div class="section-head"><div class="section-title-group"><span class="section-number">${g.number}</span><div><h3>${esc(g.title)}</h3><p>${esc(g.subtitle)}</p></div></div>${badge(stats.done+'/'+stats.all,stats.missing?'neutral':'good')}</div><div class="section-content">${g.fields?.length?`<div class="field-section">${fieldsHtml(g.fields,doc)}</div>`:''}<div class="checklist">${g.items.map(item=>renderCheckRow(doc,item)).join('')}</div></div></section>`}
function renderCheckRow(doc,item){const s=doc.checklist?.[item.id]||'todo',open=state.expanded.has(item.id),note=doc.checkNotes?.[item.id]||'';return `<div class="check-row ${s==='done'?'done':s==='na'?'na':''}" data-check-row="${item.id}"><input class="check-control" type="checkbox" aria-label="${attr(item.label)}" data-check="${item.id}" ${s==='done'?'checked':''} ${s==='na'?'title="Nicht anwendbar"':''}><div class="check-copy"><div class="check-label">${esc(item.label)}</div>${s==='na'?`<div class="check-note">Nicht anwendbar${note?' · '+esc(note):' · Begründung fehlt'}</div>`:''}${open?`<div class="check-detail"><p>${esc(item.help)}</p>${sourceLinks(item.links)}<div class="field"><label for="note-${item.id}">${s==='na'?'Begründung (erforderlich)':'Evidenz / Quelle / Notiz'}</label><textarea id="note-${item.id}" rows="2" data-check-note="${item.id}" placeholder="${s==='na'?'Warum ist dieser Punkt nicht anwendbar oder nicht verfügbar?':'Was habe ich geprüft? Quelle, Datum und kurze Erkenntnis …'}">${esc(note)}</textarea></div></div>`:''}</div><div class="check-tools"><button class="mini-action ${s==='na'?'selected':''}" data-check-na="${item.id}" title="Nicht anwendbar / Daten nicht verfügbar">N/A</button><button class="mini-action ${open?'selected good':''}" data-check-help="${item.id}" aria-expanded="${open}" aria-label="Hilfe und Notiz anzeigen">?</button></div></div>`}
function renderEvents(doc){const events=doc.events||[];return `${panel(`<div class="card-pad">${sectionHeader('Catalysts & Wirtschaftskalender','Trage die Events ein, die deinen Trade oder die Morgenanalyse tatsächlich beeinflussen.',btn('new-event','+ Event hinzufügen','primary'))}<div class="alert"><strong>Zeitzone:</strong> Zeiten werden als deine lokale Browserzeit erfasst. Prüfe die Originalzeit und Sommer-/Winterzeit. Ereignisse werden nicht automatisch aktualisiert.</div>${events.length?`<div class="list-stack">${events.slice().sort((a,b)=>String(a.at).localeCompare(String(b.at))).map(eventRow).join('')}</div>`:empty('Noch keine Catalysts','Erfasse z. B. CPI, NFP, Zentralbankentscheide oder ein relevantes geopolitisches Ereignis.','new-event','Event erfassen')}</div>`)}<div class="section-title"><h2>Kalender-Quellen</h2></div><div class="two-col">${sourceCard('calendar')}${sourceCard('tecalendar')}</div>`}
function eventRow(e){return `<div class="record-row" style="cursor:default"><div class="record-main"><div class="record-symbol">◷</div><div style="min-width:0"><div class="record-title">${esc(e.title||'Unbenanntes Event')}</div><div class="record-sub">${esc(e.currency||'Global')} · ${dateTimeFmt(e.at)}${e.forecast?' · Forecast: '+esc(e.forecast):''}${e.actual?' · Actual: '+esc(e.actual):''}</div>${e.plan?`<div class="record-sub">${esc(e.plan)}</div>`:''}</div></div><div class="record-meta">${badge(e.impact||'Unbewertet',e.impact==='High'?'warn':'neutral')}<button class="button button-ghost button-small" data-edit-event="${attr(e.id)}">Bearbeiten</button><button class="button button-ghost button-small" data-delete-event="${attr(e.id)}" aria-label="Event löschen">×</button></div></div>`}
function renderTrade(t){const tabs=[['overview','Trade-Übersicht'],['checklist','Checkliste'],['execution','Entry & Risiko'],['events','Catalysts'],['screenshots','Screenshots'],['journal','Journal']];const body=state.tab==='checklist'?renderChecklists(t):state.tab==='execution'?renderExecution(t):state.tab==='screenshots'?renderImages(t):state.tab==='events'?renderEvents(t):state.tab==='journal'?renderJournal(t):renderTradeOverview(t);return renderDetailHead(t,'TRADE-VALIDATION',t.pair||'Noch kein Paar gewählt')+renderTabs(tabs)+body}
function renderTradeOverview(t){const stats=checklistStats(t);return `<div class="review-strip"><div class="review-cell"><div class="label">Status</div><div class="value">${esc(t.status)}</div></div><div class="review-cell"><div class="label">Checklisten-Fortschritt</div><div class="value">${stats.done}/${stats.all} · ${stats.na} N/A</div></div><div class="review-cell"><div class="label">Eigene Setup-Qualität</div><div class="value">${esc(t.grade)}</div></div></div><div class="panel-grid"><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Trade-Idee','Richtung und Marktmechanismus zuerst, danach der Chart.')}<div class="form-grid">${textField('title','Titel',t.title,'z. B. USDJPY – Rates Divergence','span-2')}${field('pair','Währungspaar','text','USDJPY',null,'Sechs Buchstaben, z. B. EURUSD.','',t.pair,'maxlength="6" style="text-transform:uppercase"')}${field('direction','Richtung','select','',['Long','Short'],'','',t.direction)}${field('status','Journal-Status','select','',D.status,'„Offen“ bedeutet, dass du eine tatsächliche Position dokumentierst, nicht dass die App eine Order ausführt.','',t.status)}${field('grade','Eigene Setup-Qualität','select','',['Unbewertet','A+','A','B','C'],'Keine automatisch vergebene Qualitätsnote.','',t.grade)}</div>${boxField('fields.thesis','Fundamentale Trade-These',get(t,'fields.thesis'),'Warum sollte die Base relativ zur Quote steigen oder fallen?')}${boxField('fields.catalyst','Catalyst / dominanter Driver',get(t,'fields.catalyst'),'Was soll die Bewegung auslösen oder fortsetzen?')}${boxField('fields.fundamentalInvalidation','Was würde meine fundamentale These zerstören?',get(t,'fields.fundamentalInvalidation'),'Konkretes Repricing, Datenüberraschung oder Regimewechsel')}${boxField('notes','Weitere Trade-Notizen',t.notes,'Gedanken, offene Fragen, Watchlist …')}</div>`)}${panel(`<div class="card-pad">${sectionHeader('EdgeFinder Baseline','Hier nur das Ergebnis deines EdgeFinder-Checks übernehmen – nicht alles nochmals neu analysieren.')}<div class="form-grid">${field('fields.edgeBase','Base EdgeFinder Bias','select','',D.fields.edge[0].options,'','',get(t,'fields.edgeBase'))}${field('fields.edgeQuote','Quote EdgeFinder Bias','select','',D.fields.edge[1].options,'','',get(t,'fields.edgeQuote'))}${field('fields.edgeScoreBase','Base Score','number','Optional',null,'','',get(t,'fields.edgeScoreBase'))}${field('fields.edgeScoreQuote','Quote Score','number','Optional',null,'','',get(t,'fields.edgeScoreQuote'))}</div>${boxField('fields.edgeIncluded','Was hat EdgeFinder bereits abgedeckt?',get(t,'fields.edgeIncluded'),'Scorecard, Real Yield History, COT, Retail Sentiment, Technical, Seasonality …')}${boxField('fields.edgeGap','Welche Zusatzchecks bleiben offen?',get(t,'fields.edgeGap'),'OIS/Futures, 2Y-Differential, Market Driver, Event-Risiko, Zentralbank-Nuance …')}<div class="alert warn"><strong>Wichtig:</strong> EdgeFinder ist deine Baseline. Real Yield, COT und Sentiment aus EdgeFinder zählen nicht nochmals separat als unabhängige Bestätigung.</div></div>`)}${panel(`<div class="card-pad">${sectionHeader('Macro-Snapshot übernehmen','EdgeFinder + Zusatz-Makro einmal erfassen, mehrfach verwenden.',btn('attach-macro','Snapshot wählen','outline'))}${t.macroSnapshot?`<div class="alert good"><strong>${esc(t.macroSnapshot.title||'Makro-Snapshot')}</strong><p>Stand: ${dateFmt(t.macroSnapshot.date)} · Übernommen: ${dateTimeFmt(t.macroSnapshot.attachedAt)}. Diese Kopie ändert sich nicht, wenn die ursprüngliche Morgenanalyse bearbeitet wird.</p></div><div class="inline-actions">${t.macroId&&findRecord(t.macroId)?btn('open-linked-macro','Original öffnen','ghost'):''}${btn('attach-macro','Erneut übernehmen','outline')}</div>`:`<p class="text-small">Noch keine Morgenanalyse verknüpft. Übernimm EdgeFinder-Basis, geprüfte Zinsen, Zentralbanken und den Market Driver aus einem Snapshot. Entry und Journal bleiben trade-spezifisch.</p>${btn('attach-macro','Morgenanalyse auswählen','primary')}`}</div>`)}${panel(`<div class="card-pad">${sectionHeader('Fundamentale Einschätzung','Fünf Säulen: EdgeFinder + Zusatzchecks statt Double Counting.')}<p class="text-small">Beurteile die Faktoren relativ zur geplanten Richtung. Ein Widerspruch bleibt ein Widerspruch – die App macht daraus keinen künstlichen Score.</p><div class="factor-grid">${D.FACTORS.map(f=>renderFactor(t,f)).join('')}</div></div>`)}</div><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Trade Readiness','Ein Prüfprotokoll, kein automatisches Signal.')}<div id="readiness">${readinessHtml(t)}</div><div class="inline-actions mt-16">${btn('trade-checklist','Checkliste öffnen','outline')}${btn('trade-execution','Entry planen','outline')}</div></div>`)}${panel(`<div class="card-pad">${sectionHeader('Nächste Schritte')}<div class="callout-list">${[['1','EdgeFinder übernehmen','Bias, Score, Real Yield Proxy und Positioning sauber dokumentieren.'],['2','Zusatzchecks prüfen','OIS/Futures, 2Y-Differential, Market Driver und Events validieren.'],['3','Entry & Risiko','D1/H4/M15-Setup, Stop, CRV und Gesamt-Exposure.'],['4','Journal führen','Entscheidung, Screenshots, Management und Review festhalten.']].map(x=>`<div class="callout-item"><div class="callout-number">${x[0]}</div><div><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}</div></div>`)}${panel(`<div class="card-pad">${sectionHeader('Wichtige Catalysts',`${(t.events||[]).length} manuell erfasste Events`,btn('new-event','+ Event','ghost'))}${(t.events||[]).length?`<div class="list-stack">${t.events.slice(0,3).map(eventRow).join('')}</div>`:'<p class="text-small">Noch keine Events erfasst. Prüfe den Kalender für beide Währungen.</p>'}<div class="inline-actions mt-16">${btn('trade-events','Alle Catalysts','outline')}${sourceLink('calendar','Kalender öffnen')}</div></div>`)}</div></div>`}
function renderFactor(t,f){const v=t.factors?.[f.id]||'Unbewertet',n=t.factorNotes?.[f.id]||'';return `<div class="factor-card"><div class="factor-header"><h4>${esc(f.title)}</h4>${badge(v,v==='Bestätigt'?'good':v==='Widerspricht'?'bad':v==='Neutral'?'neutral':v==='Nicht verfügbar'?'warn':'neutral')}</div><p>${esc(f.description)}</p><div class="field mt-16"><label for="factor-${f.id}">Beurteilung</label><select id="factor-${f.id}" data-factor="${f.id}">${options(D.outcomes,v)}</select></div><div class="field"><label for="factor-note-${f.id}">Kurze Begründung</label><textarea id="factor-note-${f.id}" data-factor-note="${f.id}" rows="2" placeholder="Evidenz und wichtigste Einschränkung …">${esc(n)}</textarea></div></div>`}
function readiness(t){const issues=[],warnings=[];const pair=String(t.pair||'').toUpperCase().replace('/','');const validPair=/^[A-Z]{6}$/.test(pair)&&C.includes(pair.slice(0,3))&&C.includes(pair.slice(3))&&pair.slice(0,3)!==pair.slice(3);if(!validPair)issues.push('Gültiges FX-Paar fehlt.');if(!String(get(t,'fields.thesis')).trim())issues.push('Fundamentale Trade-These fehlt.');if(!String(get(t,'fields.fundamentalInvalidation')).trim())issues.push('Fundamentale Invalidierung fehlt.');if(!String(get(t,'fields.technicalInvalidation')).trim())issues.push('Technische Invalidierung fehlt.');if(!String(get(t,'fields.setup')).trim())issues.push('Konkretes Entry-Setup fehlt.');const r=calcRisk(t);if(!r.geometry)issues.push('Entry, Stop und Ziel fehlen oder die Preisgeometrie ist ungültig.');if(!(r.riskPercent>0))issues.push('Risiko pro Trade fehlt.');if(r.rr!==null&&r.rr<Number(state.settings.minRR))warnings.push('CRV liegt unter deinem eingestellten Mindestwert.');if(r.riskPercent>Number(state.settings.maxRisk))warnings.push('Risiko liegt über deinem eingestellten persönlichen Limit.');if(!(t.events||[]).length&&!get(t,'fields.nextEvent'))warnings.push('Noch kein konkreter Catalyst / Event-Risiko dokumentiert.');if(!t.macroSnapshot)warnings.push('Kein eingefrorener Morgenanalyse-Snapshot verknüpft.');else{const dt=new Date(t.macroSnapshot.date+'T12:00:00');if(!Number.isNaN(dt.getTime())&&(Date.now()-dt.getTime())/86400000>3)warnings.push('Der verknüpfte Makro-Snapshot ist älter als drei Tage. Prüfe die aktuellen Daten erneut.')}for(const f of D.FACTORS){if(!t.factors?.[f.id]||t.factors[f.id]==='Unbewertet')issues.push('Säule „'+f.title+'“ noch unbewertet.');else if(t.factors[f.id]==='Nicht verfügbar'&&!String(t.factorNotes?.[f.id]||'').trim())issues.push('Datenlücke bei „'+f.title+'“ nicht begründet.');else if(t.factors[f.id]==='Widerspricht')warnings.push('Säule „'+f.title+'“ widerspricht der These.')}for(const id of ['finalEvidence','finalDrivers','finalContradictions','finalEvent','finalSetup','finalIndependent']){if(t.checklist?.[id]!=='done')issues.push('Finaler Check: '+D.allItems.find(x=>x.id===id).label+'.')}for(const [id,note] of Object.entries(t.checklist||{})){if(note==='na'&&!String(t.checkNotes?.[id]||'').trim())issues.push('N/A-Begründung fehlt: '+(D.allItems.find(x=>x.id===id)?.label||id)+'.')}return {issues,warnings,ready:issues.length===0&&warnings.length===0}}
function readinessHtml(t){const r=readiness(t);const approved=!!t.approvalAt;return `<div class="alert ${r.ready?'good':r.issues.length?'warn':'warn'}"><strong>${approved?'Zuletzt freigegeben: '+dateTimeFmt(t.approvalAt):r.ready?'Die wesentlichen Prüfungen sind dokumentiert.':r.issues.length+' Pflichtpunkte offen'}</strong><p>${r.ready?'Du kannst deine Entscheidung nun bewusst dokumentieren. Dies ist keine Kauf-/Verkaufsempfehlung.':'Die App zeigt fehlende Voraussetzungen und Widersprüche an. Sie führt keine Orders aus.'}</p></div>${r.issues.length?`<div class="mini-label mb-16">Offene Pflichtpunkte</div><div class="review-list">${r.issues.slice(0,8).map(x=>`<div class="review-item bad"><span class="mark">○</span><p>${esc(x)}</p></div>`).join('')}${r.issues.length>8?`<p class="text-small mt-8">… und ${r.issues.length-8} weitere. Öffne die Checkliste.</p>`:''}</div>`:''}${r.warnings.length?`<div class="mini-label mt-16 mb-16">Warnungen & Widersprüche</div><div class="review-list">${r.warnings.map(x=>`<div class="review-item warn"><span class="mark">!</span><p>${esc(x)}</p></div>`).join('')}</div>`:''}<div class="divider"></div><div class="form-grid">${field('decision','Meine Entscheidung','select','',['Offen','Trade geplant','Kein Trade'],'','',t.decision)}${field('grade','Setup-Qualität','select','',['Unbewertet','A+','A','B','C'],'','',t.grade)}</div>${boxField('approvalNotes','Entscheidungsbegründung / bewusste Ausnahmen',t.approvalNotes,'Warum Trade / kein Trade? Welche Risiken akzeptiere ich?')}${btn('approve-trade','Entscheidung dokumentieren','primary')}`}
function renderExecution(t){const r=calcRisk(t);return `<div class="panel-grid"><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Entry & Risk Plan','Die Zahlen sind nur so zuverlässig wie deine Broker- und Kontraktdaten.')}<div class="form-grid">${field('fields.entry','Geplanter Entry','number','Preis',null,'','',get(t,'fields.entry'))}${field('fields.stop','Stop Loss','number','Preis',null,'','',get(t,'fields.stop'))}${field('fields.target','Take Profit','number','Preis',null,'','',get(t,'fields.target'))}${field('fields.riskPercent','Risiko (%)','number','0.5',null,'Prozent des Kontokapitals, kein R-Multiple.','',get(t,'fields.riskPercent'))}${field('fields.account','Kontogrösse ('+state.settings.accountCurrency+')','number','Optional',null,'','',get(t,'fields.account'))}${field('fields.pipValue','Pip-Wert pro 1 Lot ('+state.settings.accountCurrency+')','number','Brokerwert',null,'In Kontowährung, für genau dein Instrument und deine Kontraktgrösse.','',get(t,'fields.pipValue'))}${field('fields.orderType','Order-Typ','select','',['Limit','Stop','Market','Noch offen'],'','',get(t,'fields.orderType'))}${field('fields.horizon','Zeithorizont','select','',['2–5 Handelstage','1–3 Wochen','Länger / flexibel'],'','',get(t,'fields.horizon'))}</div><div id="risk-results">${riskHtml(t)}</div><div class="divider"></div>${boxField('fields.costs','Kosten / Spread / Swap / Slippage',get(t,'fields.costs'),'Was kostet die Position über die geplante Haltedauer?')}${boxField('fields.executionPlan','Entry- und Management-Plan',get(t,'fields.executionPlan'),'Trigger, Teilgewinne, Stop-Anpassung, News-Management …')}${boxField('fields.technicalInvalidation','Technische Invalidierung',get(t,'fields.technicalInvalidation'),'Welche Struktur darf nicht brechen?')}</div>`)}${panel(`<div class="card-pad">${sectionHeader('Technisches Setup','D1 / H4 / M15 entsprechend deinem Plan.')}${fieldsHtml(D.fields.technical,t)}<div class="inline-actions">${btn('trade-checklist','Technische Checkliste','outline')}${btn('trade-screenshots','Charts hochladen','outline')}</div></div>`)}</div><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Risk-Gates')}<div id="risk-gates">${renderRiskGates(t)}</div><div class="form-note mt-16 no-margin">Die Positionsgrössen-Schätzung setzt einen korrekten Pip-Wert pro Lot in Kontowährung voraus. Für CFDs, Futures oder andere Kontraktgrössen müssen die Broker-Spezifikationen verwendet werden. Die App sendet keine Orders.</div></div>`)}${panel(`<div class="card-pad">${sectionHeader('Exposure & Prop-Regeln')}${fieldsHtml(D.fields.exposure,t)}</div>`)}${panel(`<div class="card-pad">${sectionHeader('Realisierter Trade','Optional: Ergebnis nach dem Schliessen dokumentieren.')}<div class="form-grid">${field('exitPrice','Exit-Preis','number','Tatsächlicher Schlusskurs',null,'','',t.exitPrice)}${field('closedAt','Geschlossen am','datetime-local','',null,'','',t.closedAt)}${field('realizedR','Realisierte R','number','z. B. 2.15',null,'Nach tatsächlichen Kosten und Teilverkäufen dokumentieren.','',t.realizedR)}${field('realizedPnl','Realisierter P/L ('+state.settings.accountCurrency+')','number','Optional',null,'','',t.realizedPnl)}</div><p class="text-small">Das Ergebnis wird nicht automatisch aus geplanten Kursen berechnet: Teilverkäufe, Slippage, Swap und Gebühren können das tatsächliche R verändern.</p>${btn('trade-journal','Zum Journal','outline')}</div>`)}</div></div>`}
function calcRisk(t){const e=num(get(t,'fields.entry')),s=num(get(t,'fields.stop')),tg=num(get(t,'fields.target')),pct=num(get(t,'fields.riskPercent')),account=num(get(t,'fields.account')),pipValue=num(get(t,'fields.pipValue'));const geometry=e!==null&&s!==null&&tg!==null&&e>0&&s>0&&tg>0&&(t.direction==='Long'?s<e&&tg>e:tg<e&&s>e);const d=geometry?Math.abs(e-s):null;const reward=geometry?Math.abs(tg-e):null;const rr=d?reward/d:null;const pair=String(t.pair||'').toUpperCase();const pip=pair.length===6?(pair.endsWith('JPY')?.01:.0001):null;const distPips=d!==null&&pip?d/pip:null;const riskMoney=account>0&&pct>0?account*pct/100:null;const lots=riskMoney!==null&&distPips>0&&pipValue>0?riskMoney/(distPips*pipValue):null;return {geometry,d,reward,rr,pip,distPips,riskMoney,lots,riskPercent:pct,account,pipValue}}
function riskHtml(t){const r=calcRisk(t);return `<div class="metric-result"><div class="review-cell"><div class="label">Stop-Distanz</div><div class="value numeric-value">${r.d===null?'–':fmt(r.distPips,1)+' Pips'}</div></div><div class="review-cell"><div class="label">Geplantes CRV</div><div class="value numeric-value">${r.rr===null?'–':fmt(r.rr)+' R'}</div></div><div class="review-cell"><div class="label">Risiko in ${esc(state.settings.accountCurrency)}</div><div class="value numeric-value">${r.riskMoney===null?'–':fmt(r.riskMoney)}</div></div><div class="review-cell"><div class="label">Geschätzte Lots*</div><div class="value numeric-value">${r.lots===null?'–':fmt(r.lots,3)}</div></div></div>${!r.geometry?'<div class="alert warn mt-16 no-margin">Entry, Stop und Ziel müssen zur Richtung passen: Long Stop &lt; Entry &lt; Ziel; Short Ziel &lt; Entry &lt; Stop.</div>':`<div class="form-note mt-16 no-margin">* Lots = Geldrisiko ÷ (Stop in Pips × Pip-Wert pro Lot). ${r.lots===null?'Für die Lots-Schätzung fehlen Kontogrösse, Risiko oder der broker-spezifische Pip-Wert.':'Die berechnete Grösse ist eine Schätzung und muss gegen die Broker-Kontraktspezifikation geprüft werden.'}</div>`}`}
function renderRiskGates(t){const r=calcRisk(t);const checks=[['Preisgeometrie',r.geometry,'Stop und Ziel passen zur Richtung.'],['Mindest-CRV',r.rr!==null&&r.rr>=state.settings.minRR,'Persönlicher Filter: mindestens '+fmt(state.settings.minRR,1)+'R.'],['Risiko-Limit',r.riskPercent>0&&r.riskPercent<=state.settings.maxRisk,'Persönliches Limit: maximal '+fmt(state.settings.maxRisk,2)+' % pro Trade.'],['Positionsgrösse',r.lots!==null,'Broker-Pip-Wert und Kontogrösse vorhanden.'],['Execution-Kosten',!!get(t,'fields.costs').trim(),'Spread, Swap, Gebühren und Slippage notiert.'],['Gesamt-Exposure',!!get(t,'fields.totalRisk').trim(),'Korrelation und offene Risiken geprüft.']];return `<div class="review-list">${checks.map(([label,ok,help])=>`<div class="review-item ${ok?'good':'warn'}"><span class="mark">${ok?'✓':'○'}</span><div><strong>${esc(label)}</strong><p>${esc(help)}</p></div></div>`).join('')}</div>`}
function renderJournal(t){const entries=(t.journal||[]).slice().sort((a,b)=>String(b.at).localeCompare(String(a.at)));return `<div class="panel-grid"><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Trading Journal','Dokumentiere Entscheidungen, Management und den tatsächlichen Ausgang.')}<div class="form-grid">${field('status','Trade-Status','select','',D.status,'','',t.status)}${field('closedAt','Geschlossen am','datetime-local','',null,'','',t.closedAt)}${field('realizedR','Realisierte R','number','z. B. 2.15',null,'','',t.realizedR)}${field('realizedPnl','Realisierter P/L ('+state.settings.accountCurrency+')','number','Optional',null,'','',t.realizedPnl)}</div><div class="divider"></div><h3>Neuen Journaleintrag erstellen</h3><div class="form-grid">${field('journal-date','Datum / Uhrzeit','datetime-local','',null,'','',localDateTime())}${field('journal-type','Kategorie','select','',['Analyse','Entry','Management','Exit','Review'],'','', 'Analyse')}</div><div class="field"><label for="journal-text">Notiz</label><textarea id="journal-text" rows="4" placeholder="Was ist passiert? Was habe ich entschieden, und warum?"></textarea></div>${btn('add-journal','Eintrag speichern','primary')}<div class="journal-list">${entries.length?entries.map(j=>`<div class="journal-item"><div class="journal-date">${dateTimeFmt(j.at)} · ${esc(j.type||'Notiz')}</div><p>${esc(j.text)}</p><div class="journal-footer"><span class="muted text-small">${esc(j.author||'Trading Journal')}</span><button class="button button-ghost button-small" data-delete-journal="${attr(j.id)}">Löschen</button></div></div>`).join(''):'<p class="text-small">Noch keine Journaleinträge vorhanden.</p>'}</div></div>`)}</div><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Post-Trade Review','Was war gut am Prozess, unabhängig vom P/L?')}${boxField('fields.reviewProcess','Prozessqualität',get(t,'fields.reviewProcess'),'Habe ich meinen Plan befolgt? Welche Informationen waren relevant?')}${boxField('fields.reviewMistakes','Fehler / Lerneffekte',get(t,'fields.reviewMistakes'),'Welche Fehler möchte ich künftig vermeiden?')}${boxField('fields.reviewNext','Konkrete Verbesserung',get(t,'fields.reviewNext'),'Eine überprüfbare Änderung für die nächste Analyse …')}</div>`)}${panel(`<div class="card-pad">${sectionHeader('Ergebnis',t.status==='Geschlossen'?'Abgeschlossener Trade':'Noch kein abgeschlossener Trade')}<div class="metric-result"><div class="review-cell"><div class="label">Realisierte R</div><div class="value ${num(t.realizedR)>0?'outcome-pos':num(t.realizedR)<0?'outcome-neg':''}">${num(t.realizedR)===null?'–':signed(num(t.realizedR))+'R'}</div></div><div class="review-cell"><div class="label">Realisierter P/L</div><div class="value ${num(t.realizedPnl)>0?'outcome-pos':num(t.realizedPnl)<0?'outcome-neg':''}">${num(t.realizedPnl)===null?'–':signed(num(t.realizedPnl))}</div></div></div><p class="text-small mt-16">Ein guter Trade kann verlieren und ein schlechter Trade gewinnen. Bewerte deshalb die Ausführung getrennt vom Ergebnis.</p></div>`)}</div></div>`}
function renderImages(doc){return `${panel(`<div class="card-pad">${sectionHeader('Screenshots & Chart-Belege','Bilder bleiben in deiner lokalen Browser-Datenbank.',btn('pick-images','+ Screenshots hinzufügen','primary'))}<div class="image-drop" id="image-drop" tabindex="0" role="button" aria-label="Bilder auswählen oder hier ablegen"><div class="drop-icon">▧</div><strong>Charts und Screenshots hier ablegen</strong><p>PNG, JPG, WebP oder GIF · Maximal 12 MB pro Original · Grössere Bilder werden nach Möglichkeit optimiert.</p><button class="button button-outline button-small" data-action="pick-images">Dateien auswählen</button><p>Auch mehrere Bilder gleichzeitig. Die Bilder werden nicht zu GitHub hochgeladen.</p></div><div class="image-grid" id="image-grid">${(doc.images||[]).map(id=>imageCard(id)).join('')}</div>${!(doc.images||[]).length?'<p class="text-small mt-16">Noch keine Screenshots gespeichert. Füge beispielsweise EdgeFinder Scorecard, Real Yield History, COT/Retail, D1, H4, M15 oder Yield-Chart hinzu.</p>':''}</div>`)}<div class="section-title"><h2>So dokumentierst du einen Chart</h2></div><div class="three-col">${[['EdgeFinder / Macro','Scorecard, Real Yield, Positioning oder Market-Driver-Beleg speichern.'],['H4 / Setup','Zone, Retracement, Invalidierung und erwartetes Szenario markieren.'],['M15 / Entry','Tatsächlichen Trigger und Entry/Stop dokumentieren.']].map(([a,b])=>`<div class="card card-pad"><h3>${a}</h3><p class="text-small no-margin">${b}</p></div>`).join('')}</div>`}
function imageCard(id){const a=state.assets.get(id);if(!a)return `<div class="source-card"><p>Bild nicht gefunden: ${esc(id)}</p></div>`;return `<div class="image-card"><img class="image-preview" data-img-src="${attr(id)}" data-open-image="${attr(id)}" alt="${attr(a.name)}" loading="lazy"><div class="image-info"><strong>${esc(a.name)}</strong><p>${dateTimeFmt(a.createdAt)} · ${fmt(a.size/1024,0)} KB</p><div class="field mt-8"><label for="caption-${attr(id)}">Bildnotiz</label><textarea id="caption-${attr(id)}" data-image-caption="${attr(id)}" rows="2" placeholder="D1, H4, M15, Quelle, Beobachtung …">${esc(a.caption||'')}</textarea></div><div class="image-actions"><button class="button button-outline button-small" data-open-image="${attr(id)}">Ansehen</button><button class="button button-ghost button-small" data-delete-image="${attr(id)}">Löschen</button></div></div></div>`}
function sourceCard(key){const s=D.S[key];return `<div class="source-card"><div class="source-tag">${esc(s.category)}</div><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p>${sourceLink(key,'Quelle öffnen')}</div>`}
function renderSources(){const categories=['EdgeFinder','Workflow','Kalender','Zentralbanken','Zinserwartungen','2Y & Real Yields','Positioning','Risk & Intermarket','Makro & News'];return pageHead('RESEARCH LIBRARY','EdgeFinder & Quellen','Was EdgeFinder bereits abdeckt, was du zusätzlich prüfen musst und woher du die Zusatzdaten bekommst. Keine Live-Daten und keine Zugangsdaten erforderlich.')+`<div class="alert"><strong>Wichtig bei Zinserwartungen:</strong> EdgeFinder ist deine Baseline. Diese App ist kein zweiter EdgeFinder, sondern dein Prüf- und Journal-System für die Lücken: aktuelles Repricing, 2Y-Differentials, Market Driver, Event-Risiko, technische Invalidierung und Trade-Review.</div><div class="card card-pad mb-24">${sectionHeader('Dein Recherche-Ablauf','Welche Information brauchst du – und was sagt sie aus?')}<div class="two-col">${[['01 · EdgeFinder Baseline','Scorecard, Bias, Real Yield History, COT/Retail und relevante EdgeFinder-Tools übernehmen.'],['02 · Market Pricing','Nächste Sitzung und kumuliertes Pricing über 3–12 Monate. Den Unterschied zur Vorwoche notieren.'],['03 · 2Y Differentials','Nominale 2-jährige Staatsanleiherenditen gleicher Laufzeit vergleichen. Spread Base minus Quote in bp.'],['04 · EdgeFinder Real Yield','Leitzins minus CPI YoY dokumentieren. Das ist ein Proxy und keine Anleihelaufzeit.'],['05 · Market Driver','Aktuelle Nachrichten und Marktreaktionen miteinander verbinden. Den dominanten Treiber priorisieren.'],['06 · Risk & Positioning','COT/Retail aus EdgeFinder, VIX/Aktien/Bonds und relevante Rohstoffe als Kontext verwenden.']].map(([a,b])=>`<div class="callout-item"><div class="callout-number">${a.slice(0,2)}</div><div><strong>${esc(a.slice(5))}</strong><p>${esc(b)}</p></div></div>`).join('')}</div></div><div class="section-title"><h2>Quellen nach Kategorie</h2></div>${categories.map(cat=>`<section class="source-category"><h2>${cat}</h2><div class="three-col">${Object.keys(D.S).filter(k=>D.S[k].category===cat).map(sourceCard).join('')}</div></section>`).join('')}<div class="section-title"><h2>Zentralbank-Guide nach Währung</h2></div><div class="two-col">${C.map(c=>{const x=D.CURRENCIES[c];return `<div class="source-card"><h3>${c} · ${esc(x.bank)}</h3><p>${esc(x.focus)}</p>${sourceResourceList([x.source,x.rate,x.yield,...x.other])}</div>`}).join('')}</div>`}
function renderSettings(){const last=localStorage.getItem('fxdesk-last-backup');return pageHead('DATEN & SICHERHEIT','Backup & Einstellungen','Deine Daten gehören dir. Sichere sie regelmässig, besonders bevor du den Browser wechselst oder Browserdaten löschst.')+`<div class="panel-grid"><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Vollständiges Backup','Alle Analysen, Trade-Ideen, Checklisten, Quellen, Journal-Einträge und Screenshots.')}<div class="backup-warning"><strong>GitHub Pages ist keine Cloud-Datenbank.</strong><p>Deine Trade-Daten liegen ausschliesslich im jeweiligen Browserprofil und Gerät. Private Browserfenster, gelöschte Website-Daten oder ein Gerätewechsel können sie entfernen. Nutze regelmässig den vollständigen Export.</p></div><div class="inline-actions mt-16">${btn('export','Vollständiges JSON-Backup','primary')}${btn('import','Backup importieren','outline')}</div><p class="text-small mt-16">Letzter Export: ${last?dateTimeFmt(last):'Noch kein Backup erstellt'}. Der Import bietet „Zusammenführen“ oder „Bestehende Daten ersetzen“ an. Beides wird vorab bestätigt.</p></div>`)}${panel(`<div class="card-pad">${sectionHeader('Persönliche Risk-Filter','Deine Regeln – keine allgemeinen Empfehlungen.')}<div class="form-grid">${field('settings.minRR','Mindest-CRV (R)','number','2.0',null,'Nur ein Warnfilter, kein Nachweis eines positiven Erwartungswerts.','',state.settings.minRR)}${field('settings.maxRisk','Maximales Risiko pro Trade (%)','number','1.0',null,'Dein persönliches Limit. Prop-/Broker-Regeln separat prüfen.','',state.settings.maxRisk)}${field('settings.defaultRisk','Standard-Risiko bei neuer Idee (%)','number','0.5',null,'Kann in jeder Idee angepasst werden.','',state.settings.defaultRisk)}${field('settings.accountCurrency','Kontowährung','select','',C,'','',state.settings.accountCurrency)}</div><p class="text-small no-margin">Änderungen werden automatisch lokal gespeichert. Bereits erfasste Trade-Risiken werden nicht überschrieben.</p></div>`)}${panel(`<div class="card-pad">${sectionHeader('Daten löschen','Nur bewusst und nach einem Backup.')}<p class="text-small">Du kannst einzelne Ideen oder Screenshots direkt in der jeweiligen Ansicht entfernen. Hier lassen sich alle App-Daten endgültig löschen.</p>${btn('delete-all','Alle lokalen Daten löschen','danger')}</div>`)}</div><div class="list-stack">${panel(`<div class="card-pad">${sectionHeader('Datenspeicherung','Keine Registrierung und keine Serverdatenbank.')}<div class="review-list">${[['Datenbank','IndexedDB des aktuellen Browsers'],['Screenshots','Als Bilddateien in IndexedDB'],['Backup','JSON-Datei inklusive Bilddaten'],['Hosting','Statische HTML-, CSS- und JavaScript-Dateien'],['Synchronisierung','Nicht vorhanden'],['Live-Kurse','Nicht vorhanden – deine manuellen Daten'],['Trading / Orders','Keine Brokerverbindung, keine Orderausführung']].map(([a,b])=>`<div class="review-item"><strong>${a}</strong><p style="margin-left:auto;text-align:right">${b}</p></div>`).join('')}</div></div>`)}${panel(`<div class="card-pad">${sectionHeader('So verwendest du GitHub Pages')}<div class="callout-list">${[['1','Repository anlegen','Erstelle auf GitHub ein neues Repository, z. B. fx-edgefinder-companion.'],['2','Dateien hochladen','Lade den Inhalt des ZIPs in das Hauptverzeichnis hoch, nicht das ZIP als einzelne Datei.'],['3','Pages aktivieren','Settings → Pages → Deploy from a branch → main / (root) → Save.'],['4','Seite öffnen','GitHub zeigt dir die veröffentlichte URL an. Die App speichert Daten lokal pro Browser.']].map(([n,a,b])=>`<div class="callout-item"><div class="callout-number">${n}</div><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</div><div class="inline-actions mt-16"><a class="button button-outline" href="https://docs.github.com/en/pages/getting-started-with-github-pages/creating-a-github-pages-site" target="_blank" rel="noopener noreferrer">GitHub-Anleitung ↗</a></div></div>`)}${panel(`<div class="card-pad">${sectionHeader('Version 2.0 · Hinweise')}<p class="text-small">Die App ist eine EdgeFinder-Ergänzung, Dokumentations- und Planungssoftware. Sie enthält keine Live-Datenanbindung, keine KI-API, keine Cloud-Synchronisierung und keine automatische Handelsfunktion. Ein Freigabe-Häkchen ersetzt keine eigenständige Risikoentscheidung.</p><p class="text-small no-margin">Für spätere Cloud-Synchronisierung wäre eine authentifizierte Datenbank mit Zugriffskontrolle, Backups und einer klaren Migration erforderlich. Veröffentliche niemals API-Schlüssel oder private Zugangsdaten in einem GitHub-Repository.</p></div>`)}</div></div>`}
function replaceCheckRow(id){const doc=current(),item=D.allItems.find(x=>x.id===id);if(!doc||!item)return;const row=document.querySelector(`[data-check-row="${id}"]`);if(row){const holder=document.createElement('div');holder.innerHTML=renderCheckRow(doc,item);row.replaceWith(holder.firstElementChild)}refreshChecklistStats()}
function refreshChecklistStats(){const doc=current();if(!doc||state.tab!=='checklist')return;const groups=doc.kind==='macro'?D.groups.filter(g=>g.macro):D.groups;const s=checklistStats(doc,groups);const values=$$('.review-strip .review-cell .value');if(values.length>=3){values[0].textContent=s.done+' / '+s.all;values[1].textContent=s.na+' begründet';values[2].textContent=s.missing;}for(const g of groups){const el=$('#section-'+g.id);if(!el)continue;const ss=checklistStats(doc,[g]);const p=el.querySelector('.section-head .pill');if(p){p.textContent=ss.done+'/'+ss.all;p.className='pill '+(ss.missing?'neutral':'good')}}}
function refreshLive(){if(state.route==='trade'&&current()){const t=current();const r=$('#risk-results');if(r)r.innerHTML=riskHtml(t);const g=$('.panel-grid #risk-gates');if(g)g.innerHTML=renderRiskGates(t);const ready=$('#readiness');if(ready)ready.innerHTML=readinessHtml(t)}if(state.route==='macro'&&current()){const s=$('#macro-spread');if(s)s.innerHTML=spreadHtml(current())}refreshImageSources()}
function refreshImageSources(){for(const el of $$('img[data-img-src]')){const id=el.dataset.imgSrc,a=state.assets.get(id);if(a){if(!state.imageUrls.has(id))state.imageUrls.set(id,URL.createObjectURL(a.blob));el.src=state.imageUrls.get(id)}}}
function invalidateApproval(doc,key){if(doc.kind!=='trade'||!doc.approvalAt)return;if(key.startsWith('journal')||['status','realizedR','realizedPnl','exitPrice','closedAt','notes','approvalNotes','grade','decision'].includes(key)||key.startsWith('fields.review'))return;doc.approvalAt='';if(doc.status==='Bereit')doc.status='Watchlist';}
function handleBound(el){const doc=current(),key=el.dataset.bind;if(!key)return;let value=el.value;if(key==='pair')value=value.toUpperCase().replace(/[^A-Z]/g,'').slice(0,6);if(el.type==='number')value=value.replace(',','.');if(key.startsWith('settings.')){set(state,key,value);markDirty();return}if(!doc)return;if(key.startsWith('pairs.')){const parts=key.split('.'),id=parts[1],prop=parts.slice(2).join('.');if(!Array.isArray(doc.pairs))doc.pairs=[];let p=doc.pairs.find(x=>x.id===id);if(!p){p={id};doc.pairs.push(p)}if(prop==='pair')value=value.toUpperCase().replace(/[^A-Z]/g,'').slice(0,6);p[prop]=value;updateRecord(doc);if(['direction','status','confidence','edge','rates','driver','technical'].includes(prop)||(prop==='pair'&&value.length===6))render();return}set(doc,key,value);if(key==='pair'&&doc.kind==='trade'&&doc.title==='Neue Trade-Idee'&&value.length===6)doc.title=value+' · '+doc.direction;if(key==='status'&&doc.kind==='trade'&&value==='Geschlossen'&&!doc.closedAt)doc.closedAt=localDateTime();invalidateApproval(doc,key);updateRecord(doc);if(key==='pair'||key==='direction'||key==='status'||key==='title'||key==='grade'||key==='decision'||key==='date'){$('#breadcrumbs').innerHTML=`Workspace <span>/</span> ${doc.kind==='trade'?'Trade-Idee':'Morgenanalyse'} <span>/</span> ${esc(doc.title)}`;if(key==='title'||key==='pair')$('.detail-banner h1')?.replaceChildren(document.createTextNode(doc.title));}if(['fields.entry','fields.stop','fields.target','fields.riskPercent','fields.account','fields.pipValue','direction','pair','fields.compareBase','fields.compareQuote'].includes(key))refreshLive();if(key==='fields.compareBase'||key==='fields.compareQuote')refreshLive();}
function handleCheck(id,kind){const doc=current();if(!doc)return;const old=doc.checklist[id]||'todo';const next=kind==='na'?(old==='na'?'todo':'na'):(old==='done'?'todo':'done');doc.checklist[id]=next;if(next==='na')state.expanded.add(id);invalidateApproval(doc,'checklist.'+id);updateRecord(doc);replaceCheckRow(id)}
function handleCheckHelp(id){if(state.expanded.has(id))state.expanded.delete(id);else state.expanded.add(id);replaceCheckRow(id)}
function handleNote(el){const doc=current();if(!doc)return;doc.checkNotes[el.dataset.checkNote]=el.value;invalidateApproval(doc,'checklist.'+el.dataset.checkNote);updateRecord(doc);const row=el.closest('.check-row');if(row?.classList.contains('na')){const note=row.querySelector('.check-note');if(note)note.textContent='Nicht anwendbar · '+(el.value||'Begründung fehlt')}}
function renderEventEditor(id=null){const doc=current();if(!doc)return;const e=doc.events.find(x=>x.id===id)||{id:uid(),title:'',at:localDateTime(),currency:doc.kind==='trade'?(doc.pair||'Global'):'Global',forecast:'',actual:'',impact:'High',plan:''};state.editingEvent=e.id;modal(id?'Event bearbeiten':'Catalyst erfassen',`<div class="form-grid">${field('modal-event-title','Event / Veröffentlichung','text','z. B. US CPI',null,'','span-2',e.title)}${field('modal-event-at','Datum / lokale Uhrzeit','datetime-local','',null,'','',e.at)}${field('modal-event-currency','Währung / Region','text','USD, EUR, Global …',null,'','',e.currency)}${field('modal-event-impact','Erwartete Bedeutung','select','',['Low','Medium','High'],'','',e.impact)}${field('modal-event-forecast','Konsens / Forecast','text','Optional',null,'','',e.forecast)}${field('modal-event-actual','Actual / Ergebnis','text','Optional',null,'','',e.actual)}</div><div class="field"><label for="modal-event-plan">Risiko und Handlungsplan</label><textarea id="modal-event-plan" rows="3" placeholder="Was könnte passieren? Was tue ich davor/danach?">${esc(e.plan)}</textarea></div>`,btn('close-modal','Abbrechen')+btn('save-event','Event speichern','primary'))}
function saveEvent(){const doc=current();if(!doc)return;const title=$('#modal-event-title')?.value.trim();if(!title){toast('Bitte einen Event-Namen eingeben.','error');return}const e={id:state.editingEvent||uid(),title,at:$('#modal-event-at').value,currency:$('#modal-event-currency').value.trim(),impact:$('#modal-event-impact').value,forecast:$('#modal-event-forecast').value.trim(),actual:$('#modal-event-actual').value.trim(),plan:$('#modal-event-plan').value.trim()};const i=doc.events.findIndex(x=>x.id===e.id);if(i>=0)doc.events[i]={...doc.events[i],...e};else doc.events.push(e);updateRecord(doc);closeModal();render();toast('Event gespeichert.')}
function attachMacro(){const t=current();if(!t||t.kind!=='trade')return;const macros=macroRecords();if(!macros.length){confirmAction('Noch keine Morgenanalyse','Erstelle zuerst eine Morgenanalyse. Danach kannst du deren Makro-Daten und Checkliste in einen Trade übernehmen.',()=>create('macro'),'Morgenanalyse erstellen');return}modal('Makro-Snapshot übernehmen',`<p>Wähle die Analyse, deren Daten du als Grundlage verwenden möchtest. Die Makro-Felder und Makro-Checkboxen werden übernommen; deine EdgeFinder-Daten, technischen Setups und Trade-Notizen bleiben erhalten.</p><div class="field"><label for="attach-select">Morgenanalyse</label><select id="attach-select">${macros.map(m=>`<option value="${attr(m.id)}">${esc(m.title)} · ${dateFmt(m.date)}</option>`).join('')}</select></div><div class="alert warn"><strong>Es wird eine Kopie erstellt.</strong> Wenn du später die ursprüngliche Morgenanalyse änderst, wird die Trade-These nicht automatisch aktualisiert. Eine erneute Übernahme überschreibt die zuvor übernommenen Makro-Felder und ersetzt importierte Events.</div>`,btn('close-modal','Abbrechen')+btn('attach-confirm','Snapshot übernehmen','primary'))}
function applyMacro(t,m){const snap={id:m.id,title:m.title,date:m.date,attachedAt:now(),fields:clone(m.fields||{}),currencies:clone(m.currencies||{}),checklist:clone(m.checklist||{}),checkNotes:clone(m.checkNotes||{}),events:clone(m.events||[]),pairs:clone(m.pairs||[]),conclusion:m.conclusion||'',notes:m.notes||''};const base=t.pair.slice(0,3),quote=t.pair.slice(3,6);for(const g of D.groups.filter(x=>x.macro)){for(const f of g.fields||[]){if(m.fields?.[f.id]!==undefined)t.fields[f.id]=m.fields[f.id]}for(const item of g.items){if(m.checklist?.[item.id])t.checklist[item.id]=m.checklist[item.id];if(m.checkNotes?.[item.id]!==undefined)t.checkNotes[item.id]=m.checkNotes[item.id]}}const a=m.currencies?.[base]||{},b=m.currencies?.[quote]||{};if(C.includes(base)&&C.includes(quote)){t.fields.policyBase=D.CURRENCIES[base].bank+(a.bankRate?' · '+a.bankRate+' %':'');t.fields.policyQuote=D.CURRENCIES[quote].bank+(b.bankRate?' · '+b.bankRate+' %':'');t.fields.policyPricing=base+': '+(a.pricingNext||'keine Angabe')+' bp nächste Sitzung, '+(a.pricing12m||'keine Angabe')+' bp 12M\n'+quote+': '+(b.pricingNext||'keine Angabe')+' bp nächste Sitzung, '+(b.pricing12m||'keine Angabe')+' bp 12M';t.fields.policyChange=base+': '+(a.pricingChange||'keine Angabe')+' bp; '+quote+': '+(b.pricingChange||'keine Angabe')+' bp';for(const [k,x,y] of [['yieldBase',a.yield2,b.yield2],['yieldQuote',b.yield2,a.yield2],['realBase',a.real,b.real],['realQuote',b.real,a.real]]){if(x!==undefined&&x!=='')t.fields[k]=x}if(a.yield2Prev!==undefined&&b.yield2Prev!==undefined&&a.yield2Prev!==''&&b.yield2Prev!=='')t.fields.yieldPrev=String((Number(a.yield2Prev)-Number(b.yield2Prev))*100);if(a.yield2Prev2!==undefined&&b.yield2Prev2!==undefined&&a.yield2Prev2!==''&&b.yield2Prev2!=='')t.fields.yieldPrev2=String((Number(a.yield2Prev2)-Number(b.yield2Prev2))*100);t.fields.realTenor=a.realTenor&&a.realTenor===b.realTenor?a.realTenor:'';t.fields.realSource=[a.source,b.source].filter(Boolean).join('\n');t.fields.yieldSource=[a.source,b.source].filter(Boolean).join('\n');t.fields.yieldNotes=[a.notes,b.notes].filter(Boolean).join('\n')}if(m.fields?.marketSummary&&!t.fields.driverMain)t.fields.driverMain=m.fields.marketSummary;t.events=(t.events||[]).filter(e=>!e.sourceMacro).concat((m.events||[]).map(e=>({...clone(e),id:uid(),sourceMacro:m.id,sourceEvent:e.id})));t.macroSnapshot=snap;t.macroId=m.id;invalidateApproval(t,'macroSnapshot');updateRecord(t)}
function confirmAttach(){const t=current(),m=findRecord($('#attach-select')?.value);if(!t||!m)return;applyMacro(t,m);closeModal();render();toast('Makro-Snapshot übernommen und eingefroren.')}
function approvalModal(){const t=current();if(!t)return;const r=readiness(t);const risky=r.issues.length||r.warnings.length;modal('Trade-Entscheidung dokumentieren',`<p>Du entscheidest selbst, ob du den Trade planst oder verwirfst. Die App führt keine Order aus.</p>${risky?`<div class="alert warn"><strong>${r.issues.length} offene Pflichtpunkte · ${r.warnings.length} Warnungen</strong><p>${esc([...r.issues,...r.warnings].slice(0,6).join(' · '))}</p></div>`:'<div class="alert good"><strong>Die wesentlichen Prüfungen sind dokumentiert.</strong><p>Das bedeutet nicht, dass der Trade eine positive Gewinnerwartung hat.</p></div>'}<div class="field"><label for="approval-decision">Entscheidung</label><select id="approval-decision">${options(['Trade geplant','Kein Trade'],t.decision==='Kein Trade'?'Kein Trade':'Trade geplant')}</select></div><div class="field"><label for="approval-grade">Eigene Setup-Qualität</label><select id="approval-grade">${options(['Unbewertet','A+','A','B','C'],t.grade)}</select></div><div class="field"><label for="approval-reason">Begründung${risky?' / bewusste Ausnahmen':''}</label><textarea id="approval-reason" rows="4" placeholder="Warum ist diese Entscheidung sinnvoll? Welche Risiken akzeptiere ich?">${esc(t.approvalNotes||'')}</textarea></div>`,btn('close-modal','Abbrechen')+btn('approval-confirm','Entscheidung speichern','primary'))}
function saveApproval(){const t=current();if(!t)return;const r=readiness(t),decision=$('#approval-decision').value,reason=$('#approval-reason').value.trim();if(decision==='Trade geplant'&&(r.issues.length||r.warnings.length)&&reason.length<15){toast('Begründe die bewusste Ausnahme mit mindestens 15 Zeichen.','error');return}t.decision=decision;t.grade=$('#approval-grade').value;t.approvalNotes=reason;t.approvalAt=now();t.checklist.finalDecision='done';if(decision==='Kein Trade')t.status='Verworfen';else if(!['Offen','Geschlossen'].includes(t.status))t.status='Bereit';t.journal.push({id:uid(),at:now(),type:'Review',text:'Entscheidung: '+decision+' · Qualität: '+t.grade+'\n'+reason+(r.issues.length||r.warnings.length?'\nBewusste Ausnahmen: '+[...r.issues,...r.warnings].join(' | '):'')});updateRecord(t);closeModal();render();toast('Entscheidung dokumentiert. Es wurde keine Order ausgeführt.')}
async function saveImageBlob(file,doc){const allowed=['image/png','image/jpeg','image/webp','image/gif'];if(!allowed.includes(file.type))throw new Error('Nicht unterstützter Bildtyp: '+file.name);if(file.size>12*1024*1024)throw new Error('Bild zu gross (max. 12 MB): '+file.name);let blob=file;if(file.type!=='image/gif'&&file.size>4*1024*1024){try{blob=await optimizeImage(file)}catch{blob=file}}const a={id:uid(),ownerId:doc.id,name:file.name.slice(0,180),type:blob.type||file.type,size:blob.size,blob,caption:'',createdAt:now()};await put('assets',a);state.assets.set(a.id,a);doc.images.push(a.id);updateRecord(doc);return a}
function optimizeImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);const scale=Math.min(1,2600/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');if(!ctx){reject(new Error('Canvas nicht verfügbar'));return}ctx.drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(b=>b?resolve(b.size<file.size?b:file):resolve(file),'image/webp',.92)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Bild konnte nicht gelesen werden.'))};img.src=url})}
async function addImages(files){const doc=current();if(!doc)return;const list=Array.from(files||[]).filter(Boolean);if(!list.length)return;let success=0,errors=[];for(const file of list){try{await saveImageBlob(file,doc);success++}catch(e){errors.push(e.message)}}await saveNow();render();if(errors.length)toast(success+' Bilder gespeichert. '+errors.join(' '),'error');else toast(success+' Screenshot(s) gespeichert.');}
async function deleteImage(id){const doc=current();if(!doc)return;doc.images=doc.images.filter(x=>x!==id);await removeUnusedAssets([id]);updateRecord(doc);render();toast('Screenshot gelöscht.');}
async function removeUnusedAssets(ids){for(const id of ids){const used=state.records.some(r=>(r.images||[]).includes(id));if(used)continue;await del('assets',id);state.assets.delete(id);if(state.imageUrls.has(id)){URL.revokeObjectURL(state.imageUrls.get(id));state.imageUrls.delete(id)}}}
function showImage(id){const a=state.assets.get(id);if(!a)return;const url=state.imageUrls.get(id)||URL.createObjectURL(a.blob);state.imageUrls.set(id,url);const host=$('#modal');host.innerHTML=`<div class="image-lightbox" role="dialog" aria-modal="true" aria-label="Screenshot ansehen"><div class="lightbox-bar"><strong>${esc(a.name)}</strong><button class="button button-outline button-small" data-action="close-modal">Schliessen ×</button></div><img src="${attr(url)}" alt="${attr(a.name)}"><div class="lightbox-bar"><span>${esc(a.caption||'Keine Bildnotiz')}</span></div></div>`}
async function deleteRecord(){const doc=current();if(!doc)return;await flush();state.records=state.records.filter(r=>r.id!==doc.id);await del('records',doc.id);await removeUnusedAssets(doc.images||[]);navigate(doc.kind==='trade'?'trades':'macros');toast('Eintrag gelöscht.');}
function duplicateRecord(){const doc=current();if(!doc)return;const copy=clone(doc);copy.id=uid();copy.title=doc.title+' · Kopie';copy.createdAt=now();copy.updatedAt=now();copy.images=[];copy.events=(copy.events||[]).map(e=>({...e,id:uid()}));if(copy.kind==='trade'){copy.status='Idee';copy.decision='Offen';copy.approvalAt='';copy.approvalNotes='';copy.journal=[];copy.exitPrice='';copy.closedAt='';copy.realizedR='';copy.realizedPnl='';copy.checklist.finalDecision='todo'}else copy.reviewed=false;state.records.unshift(copy);markDirty();navigate(copy.kind==='trade'?'trade':'macro',copy.id);toast('Kopie erstellt. Screenshots werden nicht dupliziert.')}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
const blobData=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)});
async function exportBackup(){try{await flush();$('#save-status').textContent='Backup wird erstellt …';const assets=[];for(const a of state.assets.values())assets.push({id:a.id,ownerId:a.ownerId,name:a.name,type:a.type,size:a.size,caption:a.caption,createdAt:a.createdAt,data:await blobData(a.blob)});const payload={format:'fx-edgefinder-companion-backup',version:1,exportedAt:now(),settings:clone(state.settings),records:clone(state.records),assets};download(new Blob([JSON.stringify(payload)],{type:'application/json'}),'fx-edgefinder-companion-backup-'+localDate()+'.json');localStorage.setItem('fxdesk-last-backup',now());$('#save-status').textContent='Alles gespeichert';toast('Vollständiges Backup erstellt – inklusive Screenshots.')}catch(e){$('#save-status').textContent='Backup fehlgeschlagen';toast('Backup fehlgeschlagen: '+e.message,'error')}}
function decodeImageData(value){const m=/^data:(image\/(?:png|jpeg|webp|gif));base64,([A-Za-z0-9+/=]+)$/.exec(value||'');if(!m)throw new Error('Ungültige Bilddaten im Backup.');const raw=atob(m[2]);if(raw.length>15*1024*1024)throw new Error('Ein Backup-Bild ist zu gross.');const u=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)u[i]=raw.charCodeAt(i);return new Blob([u],{type:m[1]})}
function validateBackup(data){if(!data||!['fx-edgefinder-companion-backup','fx-trade-desk-backup'].includes(data.format)||data.version!==1||!Array.isArray(data.records)||!Array.isArray(data.assets))throw new Error('Keine gültige FX-Trade-Desk-Backup-Datei (Version 1).');if(data.records.length>10000||data.assets.length>10000)throw new Error('Zu viele Einträge im Backup.');const ids=new Set();for(const r of data.records){if(!r||typeof r.id!=='string'||!['trade','macro'].includes(r.kind)||ids.has(r.id)||typeof r.fields!=='object'||!r.fields||Array.isArray(r.fields)||!Array.isArray(r.images)||!Array.isArray(r.events)||typeof r.checklist!=='object'||!r.checklist)throw new Error('Ein Backup-Eintrag ist ungültig oder doppelt.');ids.add(r.id)}const imageIds=new Set();let total=0;for(const a of data.assets){if(!a||typeof a.id!=='string'||imageIds.has(a.id)||typeof a.data!=='string')throw new Error('Ungültige Bildreferenz.');imageIds.add(a.id);total+=a.data.length;if(total>300*1024*1024)throw new Error('Backup überschreitet das unterstützte Bildvolumen.')}return data}
async function readBackup(file){if(!file)return;try{if(file.size>300*1024*1024)throw new Error('Backup-Datei ist zu gross.');const data=validateBackup(JSON.parse(await file.text()));state.importPayload=data;modal('Backup importieren',`<div class="alert warn"><strong>${data.records.length} Einträge · ${data.assets.length} Screenshots</strong><p>Erstellt: ${dateTimeFmt(data.exportedAt)}. Prüfe, ob du die richtige Datei gewählt hast. Der Import kann bei vielen Bildern Speicherplatz benötigen.</p></div><div class="field"><label for="import-mode">Import-Modus</label><select id="import-mode"><option value="merge">Zusammenführen (bestehende Daten behalten)</option><option value="replace">Alle bestehenden Daten ersetzen</option></select><span class="hint">Beim Zusammenführen erhalten importierte Einträge bei ID-Konflikten neue IDs. Der Ersetzen-Modus löscht vorher alle aktuellen lokalen Daten.</span></div><p>Ein vollständiger Export deiner jetzigen Daten vor dem Import wird empfohlen.</p>`,btn('close-modal','Abbrechen')+btn('import-confirm','Import bestätigen','primary'))}catch(e){toast('Import fehlgeschlagen: '+e.message,'error')}}
async function commitImport(){const data=state.importPayload;if(!data)return;const mode=$('#import-mode')?.value||'merge';if(mode==='replace'){confirmAction('Alle bisherigen Daten ersetzen?','Dadurch werden sämtliche lokalen Analysen, Trade-Ideen und Screenshots dieses Browsers gelöscht und durch das Backup ersetzt. Erstelle vorher einen Export, wenn du sie behalten möchtest.',()=>performImport(data,'replace'),'Alle Daten ersetzen',true)}else await performImport(data,'merge')}
async function performImport(data,mode){try{await flush();const recordMap=new Map(),assetMap=new Map();const existingR=new Set(mode==='merge'?state.records.map(r=>r.id):[]),existingA=new Set(mode==='merge'?state.assets.keys():[]);for(const r of data.records){let id=r.id;if(existingR.has(id)){id=uid()}recordMap.set(r.id,id);existingR.add(id)}for(const a of data.assets){let id=a.id;if(existingA.has(id)){id=uid()}assetMap.set(a.id,id);existingA.add(id)}const recs=data.records.map(r=>{const x=clone(r);x.id=recordMap.get(r.id);x.images=(r.images||[]).map(id=>assetMap.get(id)).filter(Boolean);if(x.macroId)x.macroId=recordMap.get(x.macroId)||x.macroId;if(x.macroSnapshot?.id&&recordMap.has(x.macroSnapshot.id))x.macroSnapshot.id=recordMap.get(x.macroSnapshot.id);x.events=(r.events||[]).map(e=>({...e,id:e.id||uid()}));x.journal=Array.isArray(r.journal)?r.journal:[];x.checkNotes=x.checkNotes||{};x.factors=x.factors||{};x.factorNotes=x.factorNotes||{};return x});const assets=[];for(const a of data.assets){const blob=decodeImageData(a.data);assets.push({id:assetMap.get(a.id),ownerId:recordMap.get(a.ownerId)||a.ownerId,name:String(a.name||'Screenshot').slice(0,180),type:blob.type,size:blob.size,caption:String(a.caption||''),createdAt:a.createdAt||now(),blob})}await new Promise((resolve,reject)=>{const tx=state.db.transaction(['records','assets','meta'],'readwrite'),rs=tx.objectStore('records'),as=tx.objectStore('assets');if(mode==='replace'){rs.clear();as.clear()}for(const r of recs)rs.put(r);for(const a of assets)as.put(a);if(mode==='replace'&&data.settings)tx.objectStore('meta').put({key:'settings',value:data.settings});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});if(mode==='replace'){for(const url of state.imageUrls.values())URL.revokeObjectURL(url);state.imageUrls.clear();state.records=recs;state.assets=new Map(assets.map(a=>[a.id,a]));state.settings={...state.settings,...(data.settings||{})}}else{state.records.push(...recs);for(const a of assets)state.assets.set(a.id,a)}state.dirty=false;closeModal();state.importPayload=null;navigate('home');toast(recs.length+' Einträge und '+assets.length+' Bilder importiert.')}catch(e){toast('Import fehlgeschlagen: '+e.message,'error')}}
async function deleteAll(){await flush();await new Promise((resolve,reject)=>{const tx=state.db.transaction(['records','assets'],'readwrite');tx.objectStore('records').clear();tx.objectStore('assets').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});for(const url of state.imageUrls.values())URL.revokeObjectURL(url);state.imageUrls.clear();state.records=[];state.assets.clear();localStorage.removeItem('fxdesk-last-backup');navigate('home');toast('Alle lokalen App-Daten gelöscht.')}
function applyListFilter(){const macro=state.route==='macros',items=macro?macroRecords():tradeRecords();const filtered=items.filter(r=>(state.filter==='all'||(macro?(state.filter==='reviewed'?r.reviewed:!r.reviewed):r.status===state.filter))&&(!state.query||[r.title,r.pair,r.direction,r.notes].join(' ').toLowerCase().includes(state.query.toLowerCase())));const el=$('#list-results');if(el)el.innerHTML=filtered.length?filtered.map(recordRow).join(''):empty('Keine Treffer','Passe deine Suche oder den Statusfilter an.');}
function addPairCandidate(){const doc=current();if(!doc||doc.kind!=='macro')return;pairList(doc);state.pairId=doc.pairs[0]?.id||'';state.tab='pairs';render();toast('Alle 21 G7-Paare sind bereits vorbereitet.')}
function deletePairCandidate(id){toast('G7-Paare sind fixe Vergleichspaare und werden nicht gelöscht. Setze den Status auf Verworfen.','error')}
function handlePairCheck(el){const doc=current();if(!doc||doc.kind!=='macro')return;const [id,key]=String(el.dataset.pairCheck||'').split('.');const p=pairData(doc,id);if(!p||!key)return;p.checks=p.checks&&typeof p.checks==='object'?p.checks:{};p.checks[key]=el.checked?'done':'todo';updateRecord(doc);render()}
function createTradeFromPair(){const doc=current();if(!doc||doc.kind!=='macro')return;const p=pairData(doc,state.pairId);if(!p){toast('Wähle zuerst ein Paar aus.','error');return}const pair=String(p.pair||'').toUpperCase().replace(/[^A-Z]/g,'').slice(0,6);if(!/^[A-Z]{6}$/.test(pair)){toast('Bitte zuerst ein gültiges Paar eintragen, z. B. USDJPY.','error');return}const t=defaultRecord('trade');t.pair=pair;t.direction=String(p.direction||'').includes('Short')?'Short':'Long';t.title=pair+' · '+t.direction;t.status='Idee';t.grade='Unbewertet';t.fields.thesis=p.thesis||'';t.fields.catalyst=get(doc,'fields.marketSummary')||'';t.fields.fundamentalInvalidation=p.invalidation||'';t.notes=p.notes||'';t.factors.edge=p.edge&&p.edge!=='Neutral/unklar'?'Bestätigt':'Unbewertet';t.factors.rates=p.rates&&p.rates.includes('Bestätigt')?'Bestätigt':p.rates==='Widerspricht'?'Widerspricht':'Unbewertet';applyMacro(t,doc);state.records.unshift(t);markDirty();navigate('trade',t.id);toast('Trade-Idee aus G7-Paar-Checkliste erstellt.')}
async function dispatch(action,el){const doc=current();switch(action){
case'new-trade':create('trade');break;case'new-macro':create('macro');break;
case'go-trades':navigate('trades');break;case'go-macros':navigate('macros');break;
case'macro-currencies':state.tab='currencies';render();break;case'macro-pairs':state.tab='pairs';render();break;case'macro-checklist':state.tab='checklist';render();break;
case'trade-checklist':state.tab='checklist';render();break;case'trade-execution':state.tab='execution';render();break;case'trade-screenshots':state.tab='screenshots';render();break;case'trade-journal':state.tab='journal';render();break;case'trade-events':state.tab='events';render();break;
case'new-event':renderEventEditor();break;case'save-event':saveEvent();break;case'add-pair':addPairCandidate();break;case'delete-pair':deletePairCandidate(el?.dataset.pairActionId);break;case'create-trade-from-pair':createTradeFromPair();break;
case'attach-macro':attachMacro();break;case'attach-confirm':confirmAttach();break;case'open-linked-macro':if(doc?.macroId)findRecord(doc.macroId)?navigate('macro',doc.macroId):toast('Originalanalyse nicht mehr vorhanden.','error');break;
case'approve-trade':approvalModal();break;case'approval-confirm':saveApproval();break;
case'toggle-review':if(doc){doc.reviewed=!doc.reviewed;updateRecord(doc);render()}break;
case'duplicate':duplicateRecord();break;
case'delete-record':if(doc)confirmAction('Eintrag löschen?','„'+doc.title+'“ und seine Screenshots werden endgültig aus der lokalen Datenbank entfernt. Ein bereits gespeicherter Makro-Snapshot in anderen Trades bleibt erhalten.',deleteRecord,'Eintrag löschen',true);break;
case'pick-images':$('#image-picker').click();break;
case'export':await exportBackup();break;case'import':$('#backup-picker').click();break;case'import-confirm':await commitImport();break;
case'delete-all':confirmAction('Alle lokalen Daten löschen?','Diese Aktion ist endgültig. Alle Analysen, Trades und Bilder dieses Browsers werden entfernt. Erstelle vorher ein vollständiges Backup.',deleteAll,'Alle Daten löschen',true);break;
case'add-journal':if(doc?.kind==='trade'){const text=$('#journal-text')?.value.trim();if(!text){toast('Bitte eine Journal-Notiz eingeben.','error');break}doc.journal.push({id:uid(),at:$('#journal-date').value||now(),type:$('#journal-type').value,text});updateRecord(doc);render();toast('Journaleintrag gespeichert.')}break;
case'expand-all':for(const g of D.groups.filter(g=>doc?.kind==='trade'||g.macro))for(const i of g.items)state.expanded.add(i.id);render();break;
case'collapse-all':state.expanded.clear();render();break;
case'print':window.print();break;
case'close-modal':closeModal();break;
case'confirm-modal':{const cb=state.pendingAction;closeModal();if(cb)await cb();break}
case'export-trade':break;
default:break}}
function installEvents(){document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){state.filter='all';navigate(nav.dataset.nav);return}const open=e.target.closest('[data-open]');if(open){const r=findRecord(open.dataset.open);if(r)navigate(r.kind==='trade'?'trade':'macro',r.id);return}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();return}const cur=e.target.closest('[data-currency]');if(cur){state.currency=cur.dataset.currency;render();return}const pt=e.target.closest('[data-pair-tab]');if(pt){state.pairId=pt.dataset.pairTab;render();return}const check=e.target.closest('[data-check-na]');if(check){handleCheck(check.dataset.checkNa,'na');return}const help=e.target.closest('[data-check-help]');if(help){handleCheckHelp(help.dataset.checkHelp);return}const edit=e.target.closest('[data-edit-event]');if(edit){renderEventEditor(edit.dataset.editEvent);return}const de=e.target.closest('[data-delete-event]');if(de){const id=de.dataset.deleteEvent,doc=current();confirmAction('Event löschen?','Dieses Event wird aus dem aktuellen Eintrag entfernt.',()=>{doc.events=doc.events.filter(x=>x.id!==id);updateRecord(doc);render()},'Löschen',true);return}const dj=e.target.closest('[data-delete-journal]');if(dj){const id=dj.dataset.deleteJournal,doc=current();confirmAction('Journaleintrag löschen?','Diese Notiz wird endgültig entfernt.',()=>{doc.journal=doc.journal.filter(x=>x.id!==id);updateRecord(doc);render()},'Löschen',true);return}const di=e.target.closest('[data-delete-image]');if(di){const id=di.dataset.deleteImage;confirmAction('Screenshot löschen?','Das Bild wird aus dieser Analyse entfernt.',()=>deleteImage(id),'Bild löschen',true);return}const oi=e.target.closest('[data-open-image]');if(oi){showImage(oi.dataset.openImage);return}const act=e.target.closest('[data-action]');if(act){e.preventDefault();try{await dispatch(act.dataset.action,act)}catch(err){toast(err.message||String(err),'error');console.error(err)}return}if(e.target.id==='modal')closeModal()});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-bind]'))handleBound(el);else if(el.matches('[data-check-note]'))handleNote(el);else if(el.matches('[data-factor-note]')){const doc=current();if(doc){doc.factorNotes[el.dataset.factorNote]=el.value;invalidateApproval(doc,'factor.'+el.dataset.factorNote);updateRecord(doc)}}else if(el.matches('[data-image-caption]')){const a=state.assets.get(el.dataset.imageCaption);if(a){a.caption=el.value;state.saveChain=state.saveChain.catch(()=>{}).then(()=>put('assets',a));$('#save-status').textContent='Speichert Bildnotiz …';state.saveChain.then(()=>$('#save-status').textContent='Alles gespeichert').catch(()=>toast('Bildnotiz konnte nicht gespeichert werden.','error'))}}else if(el.matches('[data-list-search]')){state.query=el.value;applyListFilter()}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-pair-check]')){handlePairCheck(el)}else if(el.matches('[data-check]')){handleCheck(el.dataset.check,'check')}else if(el.matches('[data-factor]')){const doc=current();if(doc){doc.factors[el.dataset.factor]=el.value;invalidateApproval(doc,'factor.'+el.dataset.factor);updateRecord(doc);const card=el.closest('.factor-card'),p=card?.querySelector('.pill');if(p){p.textContent=el.value;p.className='pill '+(el.value==='Bestätigt'?'good':el.value==='Widerspricht'?'bad':el.value==='Nicht verfügbar'?'warn':'neutral')}const ready=$('#readiness');if(ready)ready.innerHTML=readinessHtml(doc)}}else if(el.matches('[data-list-filter]')){state.filter=el.value;applyListFilter()}});
$('#menu-button').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#mobile-shade').classList.toggle('open')});$('#mobile-shade').addEventListener('click',closeMenu);
$('#theme-button').addEventListener('click',()=>{const light=document.documentElement.dataset.theme==='light';document.documentElement.dataset.theme=light?'dark':'light';localStorage.setItem('fxdesk-theme',light?'dark':'light')});
$('#image-picker').addEventListener('change',async e=>{await addImages(e.target.files);e.target.value=''});$('#backup-picker').addEventListener('change',async e=>{await readBackup(e.target.files[0]);e.target.value=''});
document.addEventListener('dragover',e=>{const zone=$('#image-drop');if(zone&&zone.contains(e.target)){e.preventDefault();zone.classList.add('dragover')}});document.addEventListener('dragleave',e=>{const zone=$('#image-drop');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('dragover')});document.addEventListener('drop',async e=>{const zone=$('#image-drop');if(zone&&zone.contains(e.target)){e.preventDefault();zone.classList.remove('dragover');await addImages(e.dataTransfer.files)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal').innerHTML)closeModal();else closeMenu()}if((e.key==='Enter'||e.key===' ')&&e.target.id==='image-drop'){e.preventDefault();$('#image-picker').click()}});
window.addEventListener('beforeunload',e=>{if(state.dirty||state.saving){e.preventDefault();e.returnValue=''}});
window.addEventListener('pagehide',()=>{for(const url of state.imageUrls.values())URL.revokeObjectURL(url)});
}
async function init(){try{document.documentElement.dataset.theme=localStorage.getItem('fxdesk-theme')||'dark';state.db=await openDB();const [records,assets,meta]=await Promise.all([all('records'),all('assets'),all('meta')]);state.records=records.filter(r=>r&&['macro','trade'].includes(r.kind)).map(r=>({...r,fields:r.fields||{},checklist:r.checklist||{},checkNotes:r.checkNotes||{},events:r.events||[],images:r.images||[],journal:r.journal||[],factors:r.factors||{},factorNotes:r.factorNotes||{}}));state.assets=new Map(assets.map(a=>[a.id,a]));const saved=meta.find(x=>x.key==='settings');if(saved?.value)state.settings={...state.settings,...saved.value};installEvents();const hash=location.hash.match(/^#\/(trade|macro)\/([a-zA-Z0-9-]+)/);if(hash&&findRecord(hash[2]))navigate(hash[1],hash[2]);else render()}catch(e){console.error(e);$('#view').innerHTML=`<div class="empty-state"><div class="empty-icon">!</div><h2>Lokale Datenbank nicht verfügbar</h2><p>${esc(e.message)}</p><p>Öffne die App über GitHub Pages oder einen lokalen Webserver in einem normalen Browserfenster. Vermeide private Fenster und deaktivierte Website-Speicherung. Es wurden keine Daten gelöscht.</p><button class="button button-outline" onclick="location.reload()">Erneut versuchen</button></div>`}}
init();
})();
